#!/usr/bin/env python3
"""Source-preserving, non-selective graph intake for the GMRI workspace.

Every accessible source is registered. Metadata-only is explicit; no source
is dropped because of its perceived importance or relationship to a theory.
"""
from __future__ import annotations
import collections
import datetime as dt
import hashlib
import io
import json
import mimetypes
import os
import re
import sqlite3
import zipfile
from pathlib import Path

TOPIC_ALIASES = {
    "ems": [r'\bems\b',r'\bparamedic\w*\b',r'\bemergency medical\b'],
    "clinical": [r'\bclinical\b',r'\bmedicine\b',r'\bmedical\b'],
    "cognitive-science": [r'\bcognition\b',r'\bcognitive\b',r'\bneurocognit\w*\b'],
    "personhood": [r'\bpersonhood\b',r'\bdigital person\b',r'\bartificial person\b'],
    "phenomenology": [r'\bphenomenolog\w*\b',r'\bsubjective experience\b'],
    "memory": [r'\bmemor\w+\b',r'\brecall\b'],
    "graph": [r'\bgraphs?\b',r'\bgraphml\b',r'\bknowledge graph\b'],
    "reasoning": [r'\breason\w*\b',r'\binference\b',r'\bhypothes\w*\b'],
    "systems": [r'\bsystem\w*\b',r'\barchitecture\b',r'\bcybernet\w*\b'],
    "agent": [r'\bagent\w*\b',r'\bautonom\w*\b'],
    "identity": [r'\bidentit\w*\b',r'\bindividuality\b',r'\bsovereignty\b'],
    "zord": [r'\bzord\b'], "pheromind": [r'\bpheromind\b'],
    "tonyai": [r'\btonyai\b',r'\btony stark ai\b'],
    "neurodatabase": [r'\bneurodatabase\b'],
    "sage": [r'\bsage\b',r'\bself.evolving agentic graph\b'],
    "dottie": [r'\bdottie\b',r'\bdottie hill\b'],
    "grizos": [r'\bgrizos\b'],"aegis": [r'\baegis\b',r'\bhowling commandos\b'],
    "gev": [r'\bgev\b',r'\bgod.s eye view\b'],
    "openviking": [r'\bopenviking\b'], "jevbox": [r'\bjevbox\b'],
    "github": [r'\bgithub\b',r'\brepositor\w*\b',r'\bgit commit\b'],
    "source-provenance": [r'\bprovenance\b',r'\breceipt\b',r'\bcitation\b'],
    "privacy": [r'\bprivacy\b',r'\bredact\w*\b',r'\bdata right\b'],
    "accessibility": [r'\baccessibil\w*\b',r'\bada\b',r'\bdisability\b'],
    "law": [r'\blegal\b',r'\blawsuit\b',r'\bcourt\b',r'\brico\b',r'\bregulator\w*\b'],
    "cybersecurity": [r'\bsecurity\b',r'\bexploit\w*\b',r'\bmalware\b',r'\bcve.\d+\b'],
    "voice": [r'\bspeech\b',r'\bvoice\b',r'\btts\b',r'\basr\b'],
    "hardware": [r'\bradeon\b',r'\bproxmox\b',r'\bgpu\b',r'\bmacintosh\b'],
    "physics": [r'\bquantum\b',r'\bphysics\b',r'\bmathematic\w*\b'],
    "ethics": [r'\bethic\w*\b',r'\bmoral injury\b'],
    "training": [r'\btraining\b',r'\bbenchmark\b',r'\bevaluation\b',r'\btest\w*\b'],
    "marvel": [r'\bmarvel\b',r'\bspider.man\b',r'\btony stark\b',r'\bpeter parker\b'],
    "research": [r'\bresearch\b',r'\bstud\w+\b',r'\bpaper\b'],
    "dynamics": [r'\bfeedback\b',r'\bsystem dynamics\b',r'\bcausal\b'],
}
PATTERNS = {key:[re.compile(p, re.I) for p in pat] for key,pat in TOPIC_ALIASES.items()}
MAX_ANALYSIS_CHARS = 30000  # For *optional* lexical tags only; full text is always stored.

def sha_bytes(data:bytes)->str: return hashlib.sha256(data).hexdigest()
def stable_id(prefix:str,*pieces)->str:
    return prefix+':'+hashlib.sha256('|'.join(map(str,pieces)).encode()).hexdigest()[:24]
def normalize_content(obj)->str:
    if obj is None: return ''
    if isinstance(obj,str):return obj
    if isinstance(obj,(int,float,bool)):return str(obj)
    if isinstance(obj,list):return '\n'.join(normalize_content(x) for x in obj)
    if isinstance(obj,dict):
        if 'parts' in obj:return normalize_content(obj['parts'])
        if 'text' in obj and isinstance(obj['text'],(str,dict,list)):return normalize_content(obj['text'])
        if 'content' in obj and isinstance(obj['content'],(str,dict,list)):return normalize_content(obj['content'])
        return json.dumps(obj,ensure_ascii=False,default=str)
    return str(obj)
def as_timestamp(t):
    if t is None or t=='': return None
    if isinstance(t,(int,float)):
        # Epoch numbers are returned verbatim; event times may predate upload.
        return float(t)
    try:
        s=str(t).strip().replace('Z','+00:00')
        return dt.datetime.fromisoformat(s).timestamp()
    except Exception:return None

def extract_topics(text:str)->set[str]:
    text=(text or '')[:MAX_ANALYSIS_CHARS]
    return {key for key, rx in PATTERNS.items() if any(p.search(text) for p in rx)}

def extract_docx(data:bytes)->list[tuple[str,str,dict]]:
    from docx import Document
    d=Document(io.BytesIO(data));sections=[]
    for i,p in enumerate(d.paragraphs):
        if p.text.strip():sections.append((f'paragraph:{i+1}',p.text,{'paragraph':i+1,'style':p.style.name if p.style else ''}))
    for it,table in enumerate(d.tables):
        for ir,row in enumerate(table.rows):
            s=' | '.join(cell.text for cell in row.cells)
            if s.strip():sections.append((f'table:{it+1}:row:{ir+1}',s,{'table':it+1,'row':ir+1}))
    return sections

def extract_pdf(data:bytes)->list[tuple[str,str,dict]]:
    import fitz
    doc=fitz.open(stream=data,filetype='pdf')
    output=[]
    for n,p in enumerate(doc):
        try:
            text=p.get_text('text',sort=True)
            images=len(p.get_images(full=False))
            output.append((f'page:{n+1}',text,{'page':n+1,'raster_images':images,'text_extracted':bool(text.strip())}))
        except Exception as e:output.append((f'page:{n+1}','',{'page':n+1,'error':str(e)}))
    return output

class GraphBuilder:
    def __init__(self, db:Path, append=False):
        self.db=Path(db);self.db.parent.mkdir(parents=True,exist_ok=True)
        self.con=sqlite3.connect(self.db)
        self.con.execute('pragma foreign_keys=ON')
        self.con.execute('pragma journal_mode=WAL')
        self.con.execute('pragma synchronous=NORMAL')
        self.con.executescript('''
        CREATE TABLE IF NOT EXISTS sources(id TEXT PRIMARY KEY,path TEXT UNIQUE, sha256 TEXT,bytes INTEGER,mime TEXT,parse_status TEXT, parent_id TEXT,metadata_json TEXT);
        CREATE INDEX IF NOT EXISTS ix_sources_sha ON sources(sha256);
        CREATE TABLE IF NOT EXISTS nodes(id TEXT PRIMARY KEY,kind TEXT NOT NULL,label TEXT,body TEXT DEFAULT '',source_id TEXT,event_ts REAL,recorded_ts REAL,metadata_json TEXT DEFAULT '{}',layers TEXT DEFAULT '["junk_drawer"]');
        CREATE INDEX IF NOT EXISTS ix_nodes_kind ON nodes(kind);
        CREATE INDEX IF NOT EXISTS ix_nodes_time ON nodes(event_ts);
        CREATE INDEX IF NOT EXISTS ix_nodes_source ON nodes(source_id);
        CREATE VIRTUAL TABLE IF NOT EXISTS nodes_fts USING fts5(node_id UNINDEXED,label,body,tokenize='unicode61');
        CREATE TABLE IF NOT EXISTS edges(id INTEGER PRIMARY KEY,src TEXT NOT NULL,dst TEXT NOT NULL,relation TEXT NOT NULL,source_id TEXT DEFAULT '',evidence_state TEXT DEFAULT 'mechanical',metadata_json TEXT DEFAULT '{}',UNIQUE(src,dst,relation,source_id));
        CREATE INDEX IF NOT EXISTS ix_edges_src ON edges(src);
        CREATE INDEX IF NOT EXISTS ix_edges_dst ON edges(dst);
        CREATE INDEX IF NOT EXISTS ix_edges_rel ON edges(relation);
        CREATE TABLE IF NOT EXISTS events(id INTEGER PRIMARY KEY, event_kind TEXT, note TEXT, event_ts REAL);
        ''')
        self.source_counter=0;self.node_counter=0;self.edge_counter=0
        self._convs={};self._topics={}
    def close(self):
        self.con.commit()
        self.con.execute('pragma wal_checkpoint(truncate)')
        self.con.close()
    def node(self,id,kind,label,body='',source_id=None,event_ts=None,recorded_ts=None,metadata=None,layers=None):
        cur=self.con.execute('INSERT OR IGNORE INTO nodes VALUES(?,?,?,?,?,?,?,?,?)',(id,kind,str(label or ''),body or '',source_id,event_ts,recorded_ts,json.dumps(metadata or {},ensure_ascii=False,default=str),json.dumps(layers or ['junk_drawer'],ensure_ascii=False)))
        if cur.rowcount:
            self.node_counter+=1
            self.con.execute('INSERT INTO nodes_fts(node_id,label,body) VALUES(?,?,?)',(id,str(label or ''),body or ''))
        return id
    def edge(self,src,dst,relation,source_id='',evidence_state='mechanical',metadata=None):
        if not src or not dst:return
        cur=self.con.execute('INSERT OR IGNORE INTO edges(src,dst,relation,source_id,evidence_state,metadata_json) VALUES(?,?,?,?,?,?)',
                (src,dst,relation,source_id or '',evidence_state,json.dumps(metadata or {},ensure_ascii=False,default=str)))
        self.edge_counter+=max(0,cur.rowcount)
    def source(self,path,data,mime,parent_id=None,status='registered',metadata=None):
        s=str(path);id=stable_id('source',s);hashval=sha_bytes(data)
        dupe=self.con.execute('select id from sources where sha256=? and id<>? limit 1',(hashval,id)).fetchone()
        self.con.execute('INSERT OR REPLACE INTO sources VALUES(?,?,?,?,?,?,?,?)',(id,s,hashval,len(data),mime,status,parent_id,json.dumps(metadata or {},ensure_ascii=False,default=str)))
        self.source_counter+=1
        nodeid=self.node(id,'source_file' if not parent_id else 'archive_member',Path(s).name,
            body='',source_id=id,metadata={'path':s,'size':len(data),'mime':mime,'sha256':hashval,'parse_status':status,**(metadata or {})},layers=['source','junk_drawer'])
        if parent_id:self.edge(parent_id,nodeid,'CONTAINS',id)
        if dupe:self.edge(nodeid,dupe[0],'SAME_BYTES_AS',id,'hash_confirmed')
        return nodeid
    def update_status(self,id,status):
        self.con.execute('UPDATE sources SET parse_status=? WHERE id=?',(status,id))
    def enrich(self,doc_id,text:str,source_id:str,section_id=None):
        # Every text is indexed. Tags are entirely optional additional connections.
        for topic in extract_topics(text):
            tid=self._topics.get(topic)
            if tid is None:
                tid=self._topics[topic]=self.node('topic:'+topic,'lexical_topic',topic,
                   metadata={'matching':'string patterns','ontology':'non-exclusive, incomplete navigation index'},layers=['context','cross_domain','junk_drawer'])
            self.edge(section_id or doc_id,tid,'MENTIONS_LEXICALLY',source_id,'unverified_lexical_match')
    def ingest_text(self,source_id,content,section='document',metadata=None):
        n=stable_id('unit',source_id,section)
        self.node(n,'text_unit',section,content,source_id=source_id,metadata=metadata or {},layers=['context','source','junk_drawer'])
        self.edge(source_id,n,'HAS_TEXT',source_id)
        self.enrich(source_id,content,source_id,n)
        return n
    def ingest_file_bytes(self,source_id,data:bytes,name):
        ext=Path(name).suffix.lower()
        if ext in ('.md','.txt','.text','.tsv','.csv','.yaml','.yml','.xml','.html','.htm','.py','.sh','.rtf','.log','.ndjson','.js','.ts','.jsonl'):
            text=data.decode('utf-8',errors='replace');self.ingest_text(source_id,text,metadata={'encoding':'utf-8 with replacement if necessary'})
            self.update_status(source_id,'full_text')
            return
        if ext=='.json':
            text=data.decode('utf-8',errors='replace')
            try:
                j=json.loads(text)
                if isinstance(j,dict) and 'messages' in j and ('conversationId' in j or 'conversation_id' in j):
                    self.ingest_2026_chat(source_id,j)
                else:self.ingest_text(source_id,text,metadata={'json_top_type':type(j).__name__})
                self.update_status(source_id,'structured_json')
            except json.JSONDecodeError:
                self.ingest_text(source_id,text);self.update_status(source_id,'unparsed_json_text')
            return
        if ext=='.pdf' or ext=='.docx':
            try:
                sections=extract_pdf(data) if ext=='.pdf' else extract_docx(data)
                for loc,text,meta in sections:
                    self.ingest_text(source_id,text,loc,meta)
                status='extracted_text_and_page_metadata' if ext=='.pdf' else 'extracted_paragraphs_and_tables'
                self.update_status(source_id,status)
            except Exception as e:
                self.update_status(source_id,'extraction_failed:'+str(e)[:100])
            return
        # All binaries registered and kept in their original sources; nothing is discarded.
        self.update_status(source_id,'metadata_only_binary')
    def ingest_root(self,root):
        root=Path(root)
        files=sorted(f for f in root.iterdir() if f.is_file() and not f.name.startswith('.'))
        for f in files:
            try:
                data=f.read_bytes()
                src=self.source(str(f.name),data,mimetypes.guess_type(f.name)[0] or 'application/octet-stream')
                if f.suffix.lower()=='.zip':
                    self.ingest_zip(src,data,f.name)
                else:self.ingest_file_bytes(src,data,f.name)
            except Exception as e:
                self.con.execute('insert into events(event_kind,note) values(?,?)',('ingest_error',f'{f.name}: {e}'))
            self.con.commit()
        return len(files)
    def ingest_zip(self,parent_id,data,filename):
        try:
            with zipfile.ZipFile(io.BytesIO(data)) as z:
                for i,item in enumerate(z.infolist()):
                    # No skipped member, including directories.
                    if item.is_dir():
                        mid=self.node(stable_id('dir',parent_id,item.filename),'archive_directory',item.filename,source_id=parent_id,layers=['source','junk_drawer'])
                        self.edge(parent_id,mid,'CONTAINS_DIRECTORY',parent_id)
                        continue
                    if item.file_size>150_000_000:
                        # Enormous members are still inventoried but not inflated.
                        mid=self.node(stable_id('large',parent_id,item.filename),'archive_member',item.filename,source_id=parent_id,
                            metadata={'size':item.file_size,'status':'not_inflated_resource_limit'},layers=['source','junk_drawer'])
                        self.edge(parent_id,mid,'CONTAINS',parent_id)
                        continue
                    member_bytes=z.read(item)
                    p=filename+'!/'+item.filename
                    sid=self.source(p,member_bytes,mimetypes.guess_type(item.filename)[0] or 'application/octet-stream',parent_id,metadata={'zip_entry':i})
                    if item.filename=='conversations.json' and filename.startswith('728cad'):
                        try:self.ingest_legacy_conversations(sid,json.loads(member_bytes),filename)
                        except Exception as e:self.update_status(sid,'legacy_conversation_parse_failure:'+str(e)[:60])
                    elif item.filename=='chat.html' and filename.startswith('728cad'):
                        # Full original HTML remains in the source ZIP. It is another projection of
                        # conversations.json, not a unique conversation branch.
                        self.update_status(sid,'projection_html_raw_in_source_archive')
                    else:self.ingest_file_bytes(sid,member_bytes,item.filename)
                self.update_status(parent_id,'zip_all_entries_registered')
        except Exception as e:self.update_status(parent_id,'zip_open_failure:'+str(e)[:90])
    def _conversation(self,conv_id,title,source_id,meta):
        cid=stable_id('conversation',conv_id)
        self.node(cid,'conversation',title or 'Untitled conversation',source_id=source_id,metadata={'conversation_id':conv_id,**meta},layers=['context','timeline','junk_drawer'])
        self.edge(source_id,cid,'CONTAINS_CONVERSATION',source_id)
        return cid
    def ingest_legacy_conversations(self,source_id,items,archive_name):
        if not isinstance(items,list): raise ValueError('expected list')
        for c in items:
            cid_raw=c.get('conversation_id') or c.get('id') or stable_id('unknown',source_id,str(len(c)))
            title=c.get('title') or 'Untitled'
            cid=self._conversation(cid_raw,title,source_id,{'record_type':'legacy_archive','create_time':c.get('create_time'),'update_time':c.get('update_time')})
            sn=stable_id('legacy_snapshot',source_id,cid_raw)
            self.node(sn,'conversation_snapshot',title,source_id=source_id,event_ts=as_timestamp(c.get('create_time')),
                recorded_ts=as_timestamp(c.get('update_time')),
                metadata={'source_archive':archive_name,'conversation_id':cid_raw,'current_node':c.get('current_node'),'mapping_count':len(c.get('mapping') or {})},layers=['timeline','context','junk_drawer'])
            self.edge(sn,cid,'SNAPSHOT_OF',source_id)
            self.edge(source_id,sn,'IN_ARCHIVE',source_id)
            mapping=c.get('mapping') or {}
            # Insert every node before any edge; preserve branch structure.
            for mid,entry in mapping.items():
                msg=entry.get('message') or {}
                role=(msg.get('author') or {}).get('role') or 'nonmessage_mapping_node'
                content=normalize_content(msg.get('content')) if msg else ''
                nid=stable_id('legacy_message',source_id,cid_raw,mid)
                self.node(nid,'message_legacy',f'{role}: {content[:92] if content else mid}',content,source_id=source_id,
                    event_ts=as_timestamp(msg.get('create_time')),
                    recorded_ts=as_timestamp(msg.get('update_time')),
                    metadata={'message_id':mid,'author_role':role,'parent':entry.get('parent'),'children':entry.get('children') or [],
                      'recipient':msg.get('recipient'),'channel':msg.get('channel'),
                      'content_type':(msg.get('content') or {}).get('content_type') if isinstance(msg.get('content'),dict) else None,
                      'status':msg.get('status'),'raw_material_in':f'{archive_name}!/conversations.json','conversation_id':cid_raw},
                    layers=['context','timeline','evidence','junk_drawer'])
                self.edge(sn,nid,'HAS_MAPPING_ENTRY',source_id)
                if content:self.enrich(nid,content,source_id)
            for mid,entry in mapping.items():
                parent=entry.get('parent')
                if parent in mapping:
                    self.edge(stable_id('legacy_message',source_id,cid_raw,parent),stable_id('legacy_message',source_id,cid_raw,mid),'PARENT_OF',source_id)
                elif parent is not None:
                    self.con.execute('insert into events(event_kind,note) values(?,?)',('missing_parent',f'{archive_name} {cid_raw} {mid} -> {parent}'))
        self.update_status(source_id,'all_legacy_conversations_mappings_indexed')
    def ingest_2026_chat(self,source_id,j):
        cr=j.get('conversationId') or j.get('conversation_id')
        title=j.get('title') or 'Untitled'
        cid=self._conversation(cr,title,source_id,{'record_type':'chatgpt_export','exported_at':j.get('exportedAt')})
        sn=stable_id('chat_snapshot',source_id,cr)
        self.node(sn,'conversation_snapshot',title,source_id=source_id,
            recorded_ts=as_timestamp(j.get('exportedAt')),
            metadata={'source_file':source_id,'exportedAt':j.get('exportedAt'),'completeness_claim':j.get('completeness'),'branchMode':j.get('branchMode'),'message_count_declared':j.get('messageCount'),'message_count_seen':len(j.get('messages') or [])},layers=['timeline','context','junk_drawer'])
        self.edge(sn,cid,'SNAPSHOT_OF',source_id)
        self.edge(source_id,sn,'CONTAINS_SNAPSHOT',source_id)
        prev=None
        for pos,msg in enumerate(j.get('messages') or []):
            idx=msg.get('index',pos)
            role=msg.get('role') or 'unknown';content=normalize_content(msg.get('text'))
            nid=stable_id('chat_message',source_id,cr,idx,pos)
            self.node(nid,'message_export',f'{role}: {content[:92]}',content,source_id=source_id,
                event_ts=as_timestamp(msg.get('createdAt') or msg.get('timestamp')),
                recorded_ts=as_timestamp(j.get('exportedAt')),
                metadata={'message_index':idx,'role':role,'source_export':source_id,'conversation_id':cr,'snapshot_position':pos},
                layers=['context','timeline','evidence','junk_drawer'])
            self.edge(sn,nid,'HAS_MESSAGE',source_id)
            if prev:self.edge(prev,nid,'NEXT_IN_EXPORTED_ORDER',source_id)
            prev=nid
            self.enrich(nid,content,source_id)
            for aidx,att in enumerate(msg.get('attachments') or []):
                aid=stable_id('attachment',source_id,cr,idx,pos,aidx)
                self.node(aid,'attachment_reference',att.get('name') or att.get('id') or f'attachment {aidx+1}',source_id=source_id,
                   metadata={'attachment':att,'availability':'reference_in_export_not_necessarily_local_file'},layers=['context','evidence','junk_drawer'])
                self.edge(nid,aid,'ATTACHES',source_id)
    def add_connector_repository_manifest(self,repo_names,meta=None):
        manifest_id='connector:github:oldmangrizzz:list:2026-10-28'
        self.node(manifest_id,'connector_snapshot','GitHub connected repository inventory',metadata={'listed_repo_count':len(repo_names),'retrieval':'connected GitHub connector','metadata_only':True,**(meta or {})},layers=['source','context','junk_drawer'])
        for name in repo_names:
            rid=stable_id('repository','oldmangrizzz',name)
            self.node(rid,'repository_metadata','oldmangrizzz/'+name,
                metadata={'repository':'oldmangrizzz/'+name,'not_full_history':True,'repository_url':'https://github.com/oldmangrizzz/'+name,'private_access_visibility':'unknown_unless_labeled'},layers=['source','timeline','context','junk_drawer'])
            self.edge(manifest_id,rid,'LISTS_REPOSITORY',manifest_id)
            self.enrich(rid,name,manifest_id)
    def add_external_reference(self,name,location,meta=None):
        n=stable_id('external_ref',location)
        self.node(n,'external_reference',name,metadata={'location':location,'coverage':'reference_only',**(meta or {})},layers=['source','junk_drawer'])
        return n
    def validate(self):
        self.con.commit()
        out={}
        for name,q in [('sources','select count(*) from sources'),('nodes','select count(*) from nodes'),('edges','select count(*) from edges'),
                 ('dangling_src','select count(*) from edges left join nodes n on n.id=edges.src where n.id is null'),
                 ('dangling_dst','select count(*) from edges left join nodes n on n.id=edges.dst where n.id is null')]:
            out[name]=self.con.execute(q).fetchone()[0]
        out['node_kinds']=dict(self.con.execute('select kind,count(*) from nodes group by kind'))
        out['statuses']=dict(self.con.execute('select parse_status,count(*) from sources group by parse_status'))
        out['edge_types']=dict(self.con.execute('select relation,count(*) from edges group by relation'))
        out['missing_parents']=self.con.execute("select count(*) from events where event_kind='missing_parent'").fetchone()[0]
        out['extraction_errors']=self.con.execute("select count(*) from events where event_kind='ingest_error'").fetchone()[0]
        return out

