"""Read-only evidence connector for the GMRI SQLite knowledge graph."""
from __future__ import annotations
import re
import sqlite3
from pathlib import Path
from urllib.parse import quote

class EvidenceGraph:
    def __init__(self, path):
        self.path=Path(path).expanduser().resolve()
        if not self.path.is_file() or self.path.stat().st_size==0:
            raise FileNotFoundError(f'Graph database not found or empty: {self.path}')
        with self.connect() as cx:
            names={x[0] for x in cx.execute("SELECT name FROM sqlite_master WHERE type='table'")}
            if not {'sources','nodes','edges','nodes_fts'} <= names:
                raise ValueError('Graph must expose sources, nodes, nodes_fts and edges')
    def connect(self):
        return sqlite3.connect('file:'+quote(str(self.path),safe='/')+'?mode=ro&immutable=1',uri=True,timeout=10)
    def exists(self,node_id):
        with self.connect() as cx:
            return cx.execute('SELECT EXISTS(SELECT 1 FROM nodes WHERE id=?)',(node_id,)).fetchone()[0]==1
    def stats(self):
        with self.connect() as cx:
            return {name:cx.execute('SELECT count(*) FROM '+name).fetchone()[0] for name in ('sources','nodes','edges')}
    def search(self,question,limit=8):
        if not isinstance(question,str) or len(question)>20000:
            raise ValueError('Search text missing or oversized')
        tokens=re.findall(r'\w{3,}',question.lower(),flags=re.UNICODE)
        dedup=list(dict.fromkeys(tokens))[:18]
        if not dedup:return []
        expr=' OR '.join('"'+t.replace('"','')+'"' for t in dedup)
        with self.connect() as cx:
            cx.row_factory=sqlite3.Row
            rows=cx.execute('''SELECT n.id,n.kind,n.label,n.body,n.source_id,
                                     COALESCE(s.path,'') AS source_path,
                                     COALESCE(s.sha256,'') AS source_sha256,
                                     COALESCE(n.metadata_json,'{}') AS metadata_json
                              FROM nodes_fts f JOIN nodes n ON n.id=f.node_id
                              LEFT JOIN sources s ON s.id=n.source_id
                              WHERE nodes_fts MATCH ?
                              ORDER BY bm25(nodes_fts) LIMIT ?''',(expr,min(40,max(1,int(limit))))).fetchall()
        return [dict(node_id=r['id'],kind=r['kind'],title=r['label'] or '',
                     excerpt=(r['body'] or '')[:1600],source_id=r['source_id'],
                     source_path=r['source_path'],source_sha256=r['source_sha256'],
                     evidence_state='UNVERIFIED_SOURCE',retrieval='fts5',untrusted=True)
                for r in rows]
