"""Optional local OpenAI-compatible model adapter, no silent remote data egress."""
from __future__ import annotations
import json
from urllib.parse import urlsplit
from urllib.request import Request, urlopen

class ModelError(Exception):pass

class OpenAICompatibleModel:
    def __init__(self,base_url,model_name,timeout=45):
        url=base_url.rstrip('/')
        parts=urlsplit(url)
        if parts.scheme!='http' or parts.hostname not in {'localhost','127.0.0.1','::1'}:
            raise ModelError('Only explicit localhost HTTP model providers are supported')
        if parts.username or parts.password or parts.query or parts.fragment:
            raise ModelError('Credentials, queries, and fragments prohibited in provider URL')
        if not model_name or len(model_name)>140:
            raise ModelError('Model name must be specified')
        self.base_url=url
        self.model_name=model_name
        self.timeout=timeout
    def generate(self,system,prompt,evidence):
        messages=[{'role':'system','content':system},{'role':'user','content':prompt}]
        payload={'model':self.model_name,'messages':messages,'temperature':0.1,'stream':False}
        req=Request(self.base_url+'/chat/completions',data=json.dumps(payload).encode(),headers={'Content-Type':'application/json'},method='POST')
        try:
            with urlopen(req,timeout=self.timeout) as response:
                data=response.read(2_000_000)
        except Exception as exc:
            raise ModelError('Local model unavailable: '+str(exc)) from exc
        try:
            obj=json.loads(data)
            content=obj['choices'][0]['message']['content']
            if content.strip().startswith('```'):
                content=content.strip().removeprefix('```json').removeprefix('```').removesuffix('```').strip()
            answer=json.loads(content)
            if not isinstance(answer,dict):raise ValueError('Expected object')
            return answer
        except (KeyError,IndexError,TypeError,ValueError,json.JSONDecodeError) as exc:
            raise ModelError('Local model response is not the required evidence JSON') from exc
