"""Operator command-line entrypoint. All actions are local by default."""
import argparse
import json
import os
import secrets
import sys
from pathlib import Path
from .runtime import Runtime
from .models import OpenAICompatibleModel
from .webapp import make_server


def main(argv=None):
    p=argparse.ArgumentParser(prog='gmri',description='Private Dottie / Aegis research runtime')
    p.add_argument('command',choices=['status','mission','report','search','verify','serve','identities','correct','remember','veto'])
    p.add_argument('--home',default=os.environ.get('GMRI_HOME','./gmri_state'))
    p.add_argument('--graph',default=os.environ.get('GMRI_GRAPH_DB','./GMRI_universal_stage1.sqlite'))
    p.add_argument('--model-url',default=os.environ.get('GMRI_MODEL_URL'))
    p.add_argument('--model-name',default=os.environ.get('GMRI_MODEL_NAME'))
    p.add_argument('--id',default=None,help='Stable mission key')
    p.add_argument('--question',default=None)
    p.add_argument('--agent',default=None)
    p.add_argument('--text',default=None)
    p.add_argument('--port',default=8766,type=int)
    args=p.parse_args(argv)
    model=None
    if args.model_url or args.model_name:
        if not args.model_url or not args.model_name:p.error('--model-url and --model-name must be supplied together')
        model=OpenAICompatibleModel(args.model_url,args.model_name)
    runtime=Runtime(args.home,args.graph,model=model)
    if args.command=='serve':
        token_path=Path(args.home).resolve()/'web.token'
        if token_path.exists():token=token_path.read_text().strip()
        else:
            fd=os.open(token_path,os.O_CREAT|os.O_EXCL|os.O_WRONLY,0o600)
            with os.fdopen(fd,'w') as out:out.write(secrets.token_urlsafe(36))
            token=token_path.read_text().strip()
        if len(token)<32:raise RuntimeError('Web token too short')
        srv=make_server(runtime,host='127.0.0.1',port=args.port,token=token)
        print('GMRI local-only interface: http://127.0.0.1:'+str(srv.server_port))
        print('Access token (do not publish): '+token,flush=True)
        try:srv.serve_forever()
        except KeyboardInterrupt:pass
        finally:srv.server_close()
        return 0
    if args.command=='status':answer=runtime.status()
    elif args.command=='identities':answer=runtime.identities()
    elif args.command=='mission':
        if not args.question or not args.id:p.error('mission requires --id and --question')
        answer=runtime.mission(args.question,mission_key=args.id)
    elif args.command=='report':
        if not args.id:p.error('report requires --id')
        answer=runtime.report(args.id)
    elif args.command=='search':
        if not args.question:p.error('search requires --question')
        answer=runtime.find_evidence(args.question)
    elif args.command=='verify':answer=runtime.verify_audit()
    elif args.command=='correct':
        if not args.id or not args.agent or not args.text:p.error('correct requires --id --agent --text')
        runtime.correct(args.id,args.agent,args.text,caller='operator');answer={'corrected':True}
    elif args.command=='remember':
        if not args.agent or not args.text:p.error('remember requires --agent --text')
        answer={'memory_id':runtime.remember(args.agent,args.text,caller=args.agent)}
    elif args.command=='veto':
        if not args.agent or not args.text:p.error('veto requires --agent --text')
        answer=runtime.veto(args.agent,args.text,caller=args.agent)
    print(json.dumps(answer,ensure_ascii=False,indent=2))
    return 0

if __name__=='__main__':
    try:sys.exit(main())
    except Exception as exc:
        print('GMRI_ERROR: '+str(exc),file=sys.stderr)
        sys.exit(1)
