"""Token-authenticated loopback UI. No external assets, network or tools."""
from __future__ import annotations
import hmac
import json
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path
from urllib.parse import parse_qs,urlsplit

ASSETS=Path(__file__).resolve().parent/'web'


def make_server(runtime,host='127.0.0.1',port=8766,token=None):
    if host!='127.0.0.1':raise ValueError('This release accepts loopback-only HTTP; use an authenticated HTTPS proxy for iPad access')
    if not isinstance(token,str) or len(token)<32:raise ValueError('A high-entropy token is required')

    class Handler(BaseHTTPRequestHandler):
        server_version='GMRI/0.1'
        def log_message(self,fmt,*args):pass # avoid leaking question/token to logs
        def _host_ok(self):
            host_hdr=self.headers.get('Host','')
            return host_hdr in ('localhost:'+str(self.server.server_port),'127.0.0.1:'+str(self.server.server_port))
        def _auth(self):
            a=self.headers.get('Authorization','')
            return hmac.compare_digest(a,'Bearer '+token)
        def _reply(self,code,obj):
            content=json.dumps(obj,ensure_ascii=False,separators=(',',':')).encode()
            self.send_response(code)
            self.send_header('Content-Type','application/json; charset=utf-8')
            self.send_header('Cache-Control','no-store')
            self.send_header('X-Content-Type-Options','nosniff')
            self.send_header('Content-Security-Policy',"default-src 'none'; frame-ancestors 'none'")
            self.send_header('Content-Length',str(len(content)))
            self.end_headers();self.wfile.write(content)
        def _asset(self,path,mime):
            data=path.read_bytes()
            self.send_response(200)
            self.send_header('Content-Type',mime)
            self.send_header('Cache-Control','no-store')
            self.send_header('X-Content-Type-Options','nosniff')
            self.send_header('X-Frame-Options','DENY')
            self.send_header('Referrer-Policy','no-referrer')
            self.send_header('Content-Security-Policy',"default-src 'none'; script-src 'self'; style-src 'self'; connect-src 'self'; base-uri 'none'; form-action 'none'; frame-ancestors 'none'")
            self.send_header('Content-Length',str(len(data)))
            self.end_headers();self.wfile.write(data)
        def _gate(self):
            if not self._host_ok():self._reply(403,{'error':'invalid_host'});return False
            if not self._auth():self._reply(401,{'error':'unauthorized'});return False
            return True
        def do_GET(self):
            if not self._host_ok():self._reply(403,{'error':'invalid_host'});return
            u=urlsplit(self.path)
            if u.path=='/':return self._asset(ASSETS/'index.html','text/html; charset=utf-8')
            if u.path=='/ui/app.js':return self._asset(ASSETS/'app.js','text/javascript; charset=utf-8')
            if u.path=='/ui/base.css':return self._asset(ASSETS/'base.css','text/css; charset=utf-8')
            if not self._gate():return
            try:
                q=parse_qs(u.query,keep_blank_values=False)
                if u.path=='/api/status':return self._reply(200,runtime.status())
                if u.path=='/api/identities':return self._reply(200,runtime.identities())
                if u.path=='/api/evidence':return self._reply(200,runtime.find_evidence(q.get('q',[''])[0],limit=15))
                if u.path=='/api/report':return self._reply(200,runtime.report(q.get('key',[''])[0]))
                if u.path=='/api/audit':return self._reply(200,runtime.verify_audit())
                self._reply(404,{'error':'not_found'})
            except (ValueError,KeyError) as exc:self._reply(400,{'error':str(exc)})
            except Exception:self._reply(500,{'error':'internal_error'})
        def do_POST(self):
            if not self._gate():return
            if self.headers.get('Content-Type','').split(';')[0].strip()!='application/json':
                return self._reply(415,{'error':'expected_json'})
            if self.headers.get('Origin') and self.headers['Origin']!='http://127.0.0.1:'+str(self.server.server_port):
                return self._reply(403,{'error':'cross_origin_rejected'})
            try:size=int(self.headers.get('Content-Length','0'))
            except ValueError:size=-1
            if not 0<size<=40000:return self._reply(413,{'error':'payload_too_large_or_empty'})
            try:
                obj=json.loads(self.rfile.read(size))
                if not isinstance(obj,dict):raise ValueError('Object required')
                if urlsplit(self.path).path=='/api/mission':
                    return self._reply(200,runtime.mission(obj['question'],obj['mission_key']))
                if urlsplit(self.path).path=='/api/correct':
                    runtime.correct(obj['mission_key'],obj['agent'],obj['text'],caller='operator')
                    return self._reply(200,{'correction_logged':True})
                return self._reply(404,{'error':'not_found'})
            except (ValueError,KeyError) as exc:return self._reply(400,{'error':str(exc)})
            except Exception:return self._reply(500,{'error':'internal_error'})

    return ThreadingHTTPServer((host,port),Handler)
