bash -lc cat > /mnt/data/GMRI_REASONING_RECONSTRUCTION_2026-10-29/ooda_layers.py <<'PY'
"""Boydian reorientation atop the GMRI typed, time-indexed evidence graph.

One ontology, multiple projections. Never treat lexical/archival adjacency as a
causal assertion. OODA decision=proposal; action=dry-run test record; feedback=
new source-grounded observation. Every revision is append-only and hash-chained.
"""
from __future__ import annotations

import datetime as dt
import hashlib
import json
import math
import sqlite3
import uuid
from collections import defaultdict, deque
from pathlib import Path

from graph import evidence_trace

ZERO='0'*64


def now_iso():
    return dt.datetime.now(dt.timezone.utc).isoformat(timespec='microseconds')


def connect(db):
    c=sqlite3.connect(str(db),timeout=30)
    c.execute('PRAGMA foreign_keys=ON')
    c.execute('PRAGMA busy_timeout=30000')
    return c


def init_ooda(db):
    with connect(db) as c:
        c.executescript('''
        CREATE TABLE IF NOT EXISTS ooda_cycle(
          id TEXT PRIMARY KEY,anchor TEXT NOT NULL REFERENCES proposition(id),
          goal TEXT NOT NULL,actor TEXT NOT NULL,started_at TEXT NOT NULL);
        CREATE TABLE IF NOT EXISTS ooda_event(
          id TEXT PRIMARY KEY,cycle_id TEXT NOT NULL REFERENCES ooda_cycle(id),
          seq INTEGER NOT NULL,kind TEXT NOT NULL,actor TEXT NOT NULL,
          proposition_id TEXT REFERENCES proposition(id),
          event_at TEXT,recorded_at TEXT NOT NULL,payload_json TEXT NOT NULL,
          prev_hash TEXT NOT NULL,event_hash TEXT NOT NULL,
          UNIQUE(cycle_id,seq));
        CREATE INDEX IF NOT EXISTS idx_ooda_cycle_events ON ooda_event(cycle_id,seq);
        ''')


def _digest(fields):
    return hashlib.sha256(json.dumps(fields,sort_keys=True,ensure_ascii=False,separators=(',',':')).encode('utf8')).hexdigest()


def _event_hash_tuple(cycle_id,event_id,seq,kind,actor,proposition_id,event_at,recorded_at,payload_json,prev_hash):
    return _digest([cycle_id,event_id,seq,kind,actor,proposition_id,event_at,recorded_at,payload_json,prev_hash])


def _append(c,cycle_id,kind,actor,payload,proposition_id=None,event_at=None):
    if not actor.strip(): raise ValueError('actor required')
    if not c.execute('select 1 from ooda_cycle where id=?',(cycle_id,)).fetchone():raise KeyError(cycle_id)
    last=c.execute('select seq,event_hash from ooda_event where cycle_id=? order by seq desc limit 1',(cycle_id,)).fetchone()
    seq=(last[0]+1) if last else 1
    prev=last[1] if last else ZERO
    eid='event:'+uuid.uuid4().hex
    timestamp=now_iso()
    payload_json=json.dumps(payload,ensure_ascii=False,sort_keys=True,separators=(',',':'))
    digest=_event_hash_tuple(cycle_id,eid,seq,kind,actor,proposition_id,event_at,timestamp,payload_json,prev)
    c.execute('''insert into ooda_event (id,cycle_id,seq,kind,actor,proposition_id,event_at,recorded_at,payload_json,prev_hash,event_hash)
                 values(?,?,?,?,?,?,?,?,?,?,?)''',
              (eid,cycle_id,seq,kind,actor,proposition_id,event_at,timestamp,payload_json,prev,digest))
    return eid


def _event(c,cycle_id,event_id,allowed=None):
    if not event_id:raise ValueError('event reference required')
    row=c.execute('select kind,payload_json,seq,proposition_id from ooda_event where id=? and cycle_id=?',(event_id,cycle_id)).fetchone()
    if not row:raise ValueError('event is not part of this cycle')
    if allowed and row[0] not in allowed:raise ValueError('event kind cannot provide requested warrant')
    return {'kind':row[0],'payload':json.loads(row[1]),'seq':row[2],'proposition_id':row[3]}


def _source(c,proposition_id):
    row=c.execute('''select s.full_text,s.text_sha256,p.quote,p.begin_offset,p.end_offset,
         p.state,s.event_at,s.recorded_at,s.locator,s.author
         from proposition p join source_document s on s.id=p.source_id where p.id=?''',(proposition_id,)).fetchone()
    if not row:raise KeyError(proposition_id)
    full,sha,quote,a,b,state,event_at,recorded_at,locator,author=row
    if hashlib.sha256(full.encode('utf8')).hexdigest()!=sha or full[a:b]!=quote:
        raise ValueError('source integrity or verbatim-span failure')
    return {'state':state,'event_at':event_at,'recorded_at':recorded_at,'locator':locator,'author':author,'sha256':sha}


def start_cycle(db,anchor,goal,actor):
    if not goal or not goal.strip():raise ValueError('goal required')
    with connect(db) as c:
        _source(c,anchor)
        cid='ooda:'+uuid.uuid4().hex
        c.execute('insert into ooda_cycle(id,anchor,goal,actor,started_at) values(?,?,?,?,?)',
                  (cid,anchor,goal,actor,now_iso()))
        _append(c,cid,'START',actor,{'goal_verbatim':goal,'anchor':anchor})
    return cid


def observe(db,cycle_id,proposition_id,actor):
    with connect(db) as c:
        src=_source(c,proposition_id)
        return _append(c,cycle_id,'OBSERVE',actor,{'verification':'source_span_and_sha256_checked',
                       'state':src['state'],'source':src['locator'],'orientation_input':True},
                       proposition_id,src['event_at'])


def orient(db,cycle_id,interpretation,actor,based_on):
    if not interpretation or not interpretation.strip():raise ValueError('interpretation required')
    if not based_on:raise ValueError('orientation must use source observation or prior orientation')
    with connect(db) as c:
        for e in based_on:_event(c,cycle_id,e,{'OBSERVE','FEEDBACK','ORIENT'})
        count=c.execute("select count(*) from ooda_event where cycle_id=? and kind='ORIENT'",(cycle_id,)).fetchone()[0]
        return _append(c,cycle_id,'ORIENT',actor,{'interpretation':interpretation,'status':'working_orientation_not_observation',
                                      'based_on':list(based_on),'version':count+1})


def decide(db,cycle_id,hypothesis,actor,based_on):
    if not hypothesis or not hypothesis.strip():raise ValueError('hypothesis required')
    if not based_on:raise ValueError('decision hypothesis requires orientation')
    with connect(db) as c:
        for e in based_on:_event(c,cycle_id,e,{'ORIENT'})
        return _append(c,cycle_id,'DECIDE',actor,{'hypothesis':hypothesis,
                                    'status':'hypothesis_not_test_result','based_on':list(based_on)})


def act(db,cycle_id,test_description,actor,decision_event=None,scope='read_only',implicit=False,orientation_event=None):
    """Record a proposed read-only test; never execute a tool or outside side effect.

    The implicit guidance branch is only admissible for local read-only tests.
    All actual actions must be performed by a separately authorized execution runner.
    """
    if scope!='read_only':raise ValueError('external, mutating, or privileged execution is not authorized')
    if not test_description or not test_description.strip():raise ValueError('test required')
    with connect(db) as c:
        if implicit:
            if decision_event:raise ValueError('cannot combine explicit and implicit path')
            _event(c,cycle_id,orientation_event,{'ORIENT'})
            source=[orientation_event]
        else:
            _event(c,cycle_id,decision_event,{'DECIDE'})
            source=[decision_event]
        return _append(c,cycle_id,'ACT',actor,{'test':test_description,'scope':'read_only',
                'guidance':'implicit_from_orientation' if implicit else 'explicit_decision_hypothesis',
                'based_on':source,'execution':'dry_run_record_only_no_tool_invoked'})


def feedback(db,cycle_id,proposition_id,actor,after_action):
    with connect(db) as c:
        a=_event(c,cycle_id,after_action,{'ACT'})
        src=_source(c,proposition_id)
        return _append(c,cycle_id,'FEEDBACK',actor,{'from_action':after_action,
                   'source_integrity':'verified','source_state':src['state'],
                   'action_execution':a['payload']['execution'],
                   'interpretation':'not_assigned; requires next orientation'},proposition_id,src['event_at'])


def cycle_history(db,cycle_id):
    with connect(db) as c:
        c.row_factory=sqlite3.Row
        r=c.execute('select * from ooda_event where cycle_id=? order by seq',(cycle_id,)).fetchall()
    out=[]
    for row in r:
        d=dict(row);d['payload']=json.loads(d.pop('payload_json'))
        if d['proposition_id']:
            d['source_trace']=evidence_trace(db,d['proposition_id'],depth=0)
        out.append(d)
    return out


def check_audit(db,cycle_id):
    hist=cycle_history(db,cycle_id)
    prev=ZERO
    for i,e in enumerate(hist,1):
        actual=_event_hash_tuple(e['cycle_id'],e['id'],e['seq'],e['kind'],e['actor'],
            e['proposition_id'],e['event_at'],e['recorded_at'],
            json.dumps(e['payload'],ensure_ascii=False,sort_keys=True,separators=(',',':')),prev)
        if e['seq']!=i or e['prev_hash']!=prev or e['event_hash']!=actual:
            return {'valid':False,'failure_event':e['id'],'checked_events':i-1}
        prev=actual
    return {'valid':True,'checked_events':len(hist),'tip_sha256':prev}


def _coord(node_id):
    raw=hashlib.sha256(node_id.encode('utf8')).digest()
    # Stable coordinates, not claimed to be measured neural or semantic distances.
    return [round(int.from_bytes(raw[i:i+4],'big')/4294967295*2-1,5) for i in (0,4,8)]


def _time(raw):
    if not raw:return None
    try:
        t=dt.datetime.fromisoformat(str(raw).replace('Z','+00:00'))
        return int(t.timestamp())
    except (ValueError,OverflowError):return None


def unified_view(db,anchor,depth=3,limit=180,include_universe=True,cycle_id=None):
    """Return the exact shared node/edge IDs consumed by all three views.

    A proposition/semantic edge is explicitly warranted; universe edges are
    archival/topical navigation only, regardless of lexical similarity.
    Unknown time stays null; no historical date is manufactured.
    """
    if not 0<=depth<=7 or not 1<=limit<=2500:raise ValueError('unbounded graph traversal')
    with connect(db) as c:
        c.row_factory=sqlite3.Row
        is_prop=bool(c.execute('select 1 from proposition where id=?',(anchor,)).fetchone())
        is_universe=bool(c.execute('select 1 from universe_node where node_id=?',(anchor,)).fetchone())
        if not(is_prop or is_universe):raise KeyError(anchor)
        # Cached edges are read from BOTH layers; no index keyword selection.
        relation_rows=c.execute('select src,dst,kind,warrant,method,status from reasoning_relation').fetchall()
        semantic=[dict(src=r['src'],dst=r['dst'],id='reason:'+r['src']+'|'+r['dst']+'|'+r['kind'],
             kind=r['kind'],warrant=r['warrant'],method=r['method'],status=r['status'],
             provenance='typed_warranted_relation',graph_layer='reasoning') for r in relation_rows]
        archive=[]
        if include_universe:
            for r in c.execute('select base_id,src,dst,relation,source_id,evidence_state from universe_edge'):
                archive.append({'id':'archive:'+str(r['base_id']),'src':r['src'],'dst':r['dst'],
                    'kind':r['relation'],'source_id':r['source_id'],
                    'status':r['evidence_state'] or 'uninterpreted','method':'archive_navigation_only',
                    'warrant':'Archive relationship, not an asserted reasoning or causal link',
                    'provenance':'original_archival_record','graph_layer':'archive'})
        adj=defaultdict(list)
        for e in semantic+archive:
            adj[e['src']].append(e);adj[e['dst']].append(e)
        # Bidirectional traversal changes navigation only, not edge direction.
        seen={anchor};queue=deque([(anchor,0)])
        while queue and len(seen)<limit:
            cur,h=queue.popleft()
            if h>=depth:continue
            for e in adj.get(cur,[]):
                next_id=e['dst'] if e['src']==cur else e['src']
                if next_id in seen:continue
                seen.add(next_id);queue.append((next_id,h+1))
                if len(seen)>=limit:break
        edges=[e for e in semantic+archive if e['src'] in seen and e['dst'] in seen]
        nodes=[]
        propids=[id for id in seen if c.execute('select 1 from proposition where id=?',(id,)).fetchone()]
        for n in sorted(seen):
            if n in propids:
                row=c.execute('''select p.id,p.quote,p.state,s.locator,s.author,s.event_at,s.recorded_at,s.text_sha256
                    from proposition p join source_document s on p.source_id=s.id where p.id=?''',(n,)).fetchone()
                nodes.append({'id':n,'layer':'reasoning','label':row['quote'][:135],
                    'verbatim':row['quote'],'state':row['state'],'source':row['locator'],
                    'author':row['author'],'event_at':row['event_at'],'recorded_at':row['recorded_at'],
                    'source_sha256':row['text_sha256']})
            else:
                row=c.execute('select node_id,origin_kind,origin_source_id,role,body_sha256 from universe_node where node_id=?',(n,)).fetchone()
                if row:
                    nodes.append({'id':n,'layer':'archive','label':n,'state':'UNINTERPRETED_ARCHIVE_RECORD',
                        'source':row['origin_source_id'],'body_sha256':row['body_sha256'],
                        'event_at':None,'recorded_at':None})
        if cycle_id:
            # OODA records attach to the same ontology, not a separate diagram.
            hist=cycle_history(db,cycle_id)
            previous=None
            for ev in hist:
                event_node='ooda-event:'+ev['id']
                d={'id':event_node,'layer':'ooda','label':ev['kind']+' / '+ev['actor'],
                  'state':'PROCESS_EVENT_NOT_SOURCE_FACT','source':ev['id'],
                  'event_at':ev['event_at'],'recorded_at':ev['recorded_at'],
                  'payload':ev['payload']}
                nodes.append(d)
                if previous:
                    edges.append({'id':'event-chain:'+previous+'|'+event_node,'src':previous,'dst':event_node,
                      'kind':'OODA_FOLLOWS','warrant':'Append-only recorded order','status':'process_history',
                      'method':'chronological','provenance':'ooda_audit','graph_layer':'ooda'})
                if ev['proposition_id'] and ev['proposition_id'] in seen:
                    edges.append({'id':'observed:'+event_node+'|'+ev['proposition_id'],
                     'src':event_node,'dst':ev['proposition_id'],'kind':'SOURCE_OBSERVATION',
                     'warrant':'Exact verified quote/span and SHA-256','status':'source_verified',
                     'method':'direct_verified_source','provenance':'ooda_observation','graph_layer':'ooda'})
                previous=event_node
    nodes.sort(key=lambda x:x['id'])
    edges.sort(key=lambda x:x['id'])
    return {'anchor':anchor,'nodes':nodes,'edges':edges,'limits':{'depth':depth,'max_nodes':limit},
        'total_available_universe':'all base nodes available through archive anchors; projection is a bounded neighborhood',
        'time_axes':['event_at','recorded_at'],'evidence_policy':'typed reasoning != lexical navigation != OODA process'}


def _edge_group(edge):
    kind=edge['kind']
    if kind in {'FEEDS_BACK','MODULATES','RECONTEXTUALIZES'}:return 'Recursive influences'
    if kind in {'CHALLENGES','OPPOSES','LIMITS_INFERENCE','EXPLICITLY_CONTRADICTS'}:return 'Counter-evidence and constraints'
    if kind in {'HYPOTHESIZED_CAUSAL_LINK','CONDITIONAL_IMPLICATION'}:return 'Causal candidates (unverified)'
    if kind in {'REQUIRES','SPECIFIES','CONSTRAINS'}:return 'Functional dependencies'
    if kind in {'CONCEPTUAL_BRIDGE','EXPLICIT_ANALOGY'}:return 'Cross-domain bridges'
    return 'Other warranted relations'


def project_fishbone(core):
    groups=defaultdict(list)
    # Fishbone branch labels do not confer causation on non-causal relations.
    for edge in core['edges']:
        if edge['graph_layer']=='reasoning':groups[_edge_group(edge)].append(edge)
    return {'head':core['anchor'],'node_ids':[n['id'] for n in core['nodes']],
        'edge_ids':[e['id'] for e in core['edges'] if e['graph_layer']=='reasoning'],
        'branches':[{'group':k,'edges':v} for k,v in sorted(groups.items())],
        'causal_claim_policy':'Causal candidates explicitly labeled; diagram shape alone is not proof.'}


def project_mermaid(core):
    labelmap={n['id']:n['label'] for n in core['nodes']}
    ids={n['id']:'p'+str(i) for i,n in enumerate(core['nodes'])}
    lines=['graph TD']
    for n in core['nodes']:
        label=(n.get('label') or n['id'])[:60].replace('"','\'').replace('[','(').replace(']',')').replace('<','').replace('>','')
        lines.append(f'    {ids[n["id"]]}["{label}"]')
    for e in core['edges']:
        kind=e['kind'].replace('"','')
        lines.append(f'    {ids[e["src"]]} -->|"{kind}"| {ids[e["dst"]]}')
    return {'mermaid':'\n'.join(lines),'node_ids':list(ids),'edge_ids':[e['id'] for e in core['edges']],
        'label_lookup':labelmap,'direction_preserved':True}


def project_spacetime(core):
    points=[]
    for node in core['nodes']:
        points.append({'id':node['id'],'label':node['label'],'layer':node['layer'],'state':node['state'],
            'coordinates':[*_coord(node['id']),_time(node.get('event_at'))],
            'recorded_time':_time(node.get('recorded_at')),'unknown_time':not bool(node.get('event_at'))})
    return {'node_ids':[n['id'] for n in core['nodes']],'edge_ids':[e['id'] for e in core['edges']],
        'points':points,'links':core['edges'],
        'axes':['projection_x','projection_y','projection_z','event_time'],
        'time_encoding':'unknown time stays null; 3D coordinates deterministic layout, not measured cognition'}


def view_consistency(core,fish,mer,space):
    source_nodes={n['id'] for n in core['nodes']}
    source_edges={e['id'] for e in core['edges']}
    same=(source_nodes==set(fish['node_ids'])==set(mer['node_ids'])==set(space['node_ids'])
           and source_edges==set(mer['edge_ids'])==set(space['edge_ids'])
           and set(fish['edge_ids']) <= source_edges)
    return {'same_source_graph':same,'node_count':len(source_nodes),'edge_count':len(source_edges),
       'fishbone_reasoning_edges':len(fish['edge_ids']),
       'noncausal_archive_edges':sum(e['graph_layer']=='archive' for e in core['edges'])}


def projections(db,anchor,depth=3,limit=150,cycle_id=None):
    core=unified_view(db,anchor,depth=depth,limit=limit,cycle_id=cycle_id)
    fish=project_fishbone(core);mer=project_mermaid(core);space=project_spacetime(core)
    check=view_consistency(core,fish,mer,space)
    assert check['same_source_graph']
    return {'core':core,'fishbone':fish,'mermaid':mer,'spacetime':space,'consistency':check,
            'ooda':cycle_history(db,cycle_id) if cycle_id else []}
