"""Private, localhost-only authenticated GMRI OODA + three-projection service.

The service does not execute external actions. It can only record read-only,
dry-run test intentions and evidence-backed observations.
"""
import argparse
import json
import secrets
import sqlite3
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path
from urllib.parse import parse_qs,urlparse

from graph import evidence_trace
from ooda_layers import (init_ooda,start_cycle,observe,orient,decide,act,feedback,
                         projections,cycle_history,check_audit)
from query_reasoning import fts

HERE=Path(__file__).resolve().parent
DEFAULT_DB=HERE/'GMRI_recurrent_reasoning_overlay.sqlite'
DEFAULT_BASE=HERE.parent/'GMRI_GITHUB_LIBRARY_ONLY'/'GMRI_universal_stage1.sqlite'


def make_server(db,token,bind='127.0.0.1',port=8922,base=None):
    if not token or len(token)<8:raise ValueError('server requires a real bearer token')
    if bind not in ('127.0.0.1','localhost','::1'):raise ValueError('private local server refuses non-loopback binding')
    db=Path(db).resolve()
    if not db.exists(): raise FileNotFoundError(db)
    init_ooda(db)
    base=Path(base).resolve() if base is not None else DEFAULT_BASE

    class Handler(BaseHTTPRequestHandler):
        server_version='GMRI-PrivateGraph/1.0'
        def log_message(self,fmt,*args):
            # Do not log sensitive queries or bearer tokens.
            pass

        def headers_safe(self,status,kind='application/json'):
            self.send_response(status)
            self.send_header('Content-Type',kind+'; charset=utf-8')
            self.send_header('Cache-Control','no-store')
            self.send_header('X-Content-Type-Options','nosniff')
            self.send_header('Referrer-Policy','no-referrer')
            self.send_header('Content-Security-Policy',"default-src 'self'; connect-src 'self'; script-src 'self' 'unsafe-inline'; style-src 'self' 'unsafe-inline'; img-src 'self' data:; object-src 'none'; frame-ancestors 'none'")
            self.end_headers()

        def reply(self,obj,status=200):
            body=json.dumps(obj,ensure_ascii=False,default=str).encode('utf8')
            self.headers_safe(status)
            self.wfile.write(body)

        def authorized(self):
            auth=self.headers.get('Authorization','')
            return secrets.compare_digest(auth, 'Bearer '+token)

        def get(self,qs,key,default=None):
            return qs.get(key,[default])[0]

        def do_GET(self):
            parsed=urlparse(self.path)
            if parsed.path in ('/','/index.html'):
                html=HERE/'gmri_overlays.html'
                if not html.exists():return self.reply({'error':'viewer file missing'},404)
                self.headers_safe(200,'text/html')
                return self.wfile.write(html.read_bytes())
            if not self.authorized():return self.reply({'error':'authentication required'},401)
            qs=parse_qs(parsed.query)
            try:
                if parsed.path=='/api/projections':
                    anchor=self.get(qs,'anchor','user:loops')
                    depth=int(self.get(qs,'depth','3'))
                    limit=int(self.get(qs,'limit','180'))
                    cid=self.get(qs,'cycle_id')
                    return self.reply(projections(db,anchor,depth=depth,limit=limit,cycle_id=cid))
                if parsed.path=='/api/ooda/history':
                    cid=self.get(qs,'cycle_id')
                    if not cid:raise ValueError('cycle_id required')
                    return self.reply({'events':cycle_history(db,cid),'audit':check_audit(db,cid)})
                if parsed.path=='/api/ooda/list':
                    with sqlite3.connect(db) as c:
                        rows=[dict(id=a,anchor=b,goal=d,started_at=e) for a,b,d,e in c.execute('select id,anchor,goal,started_at from ooda_cycle order by started_at desc limit 40')]
                    return self.reply({'cycles':rows})
                if parsed.path=='/api/search':
                    q=str(self.get(qs,'q',''))[:180]; query=fts(q)
                    found=[]
                    if query:
                        with sqlite3.connect(db) as c:
                            for id,quote in c.execute('''select proposition_id,quote from proposition_fts where proposition_fts match ? limit 25''',(query,)):
                                found.append({'id':id,'label':quote[:180],'layer':'reasoning','status':'retrieval_candidate_not_semantic_proof'})
                        if base.exists():
                            with sqlite3.connect('file:'+str(base)+'?mode=ro',uri=True) as c:
                                for id,label,kind in c.execute('''select n.id,n.label,n.kind from nodes_fts f join nodes n on n.id=f.node_id where nodes_fts match ? limit 25''',(query,)):
                                    found.append({'id':id,'label':label,'layer':'archive:'+kind,'status':'retrieval_candidate_not_semantic_proof'})
                    return self.reply({'matches':found,'total_returned':len(found),'completeness':'retrieval candidates only'})
                if parsed.path=='/api/node':
                    id=self.get(qs,'id')
                    if not id:raise ValueError('id required')
                    with sqlite3.connect(db) as c:
                        is_prop=c.execute('select 1 from proposition where id=?',(id,)).fetchone()
                    if is_prop:return self.reply({'layer':'reasoning','trace':evidence_trace(db,id,depth=0)})
                    if base.exists():
                        with sqlite3.connect('file:'+str(base)+'?mode=ro',uri=True) as c:
                            row=c.execute('select id,kind,label,body,source_id,metadata_json from nodes where id=?',(id,)).fetchone()
                            if row:return self.reply({'layer':'archive','id':row[0],'kind':row[1],'label':row[2],
                                'body':row[3],'source_id':row[4],'metadata_json':row[5],
                                'evidence_state':'uninterpreted_source_record'})
                    return self.reply({'error':'not found'},404)
                return self.reply({'error':'unknown endpoint'},404)
            except (ValueError,KeyError,sqlite3.Error) as e:
                return self.reply({'error':str(e)},400)

        def do_POST(self):
            if not self.authorized():return self.reply({'error':'authentication required'},401)
            parsed=urlparse(self.path)
            if not parsed.path.startswith('/api/ooda/'):
                return self.reply({'error':'unknown mutation'},404)
            if not self.headers.get('Content-Type','').startswith('application/json'):
                return self.reply({'error':'JSON required'},415)
            try:
                size=int(self.headers.get('Content-Length','0'))
                if not 0<size<=16000:raise ValueError('request length exceeds limit or is empty')
                data=json.loads(self.rfile.read(size).decode('utf8'))
                if not isinstance(data,dict):raise ValueError('JSON object required')
                path=parsed.path.rsplit('/',1)[-1]
                if path=='start':
                    return self.reply({'cycle_id':start_cycle(db,data['anchor'],data['goal'],data['actor'])})
                cid=data['cycle_id'];actor=data['actor']
                if path=='observe':result=observe(db,cid,data['proposition_id'],actor)
                elif path=='orient':result=orient(db,cid,data['interpretation'],actor,data['based_on'])
                elif path=='decide':result=decide(db,cid,data['hypothesis'],actor,data['based_on'])
                elif path=='act':result=act(db,cid,data['test'],actor,
                     decision_event=data.get('decision_event'),scope=data.get('scope','read_only'),
                     implicit=data.get('implicit',False),orientation_event=data.get('orientation_event'))
                elif path=='feedback':result=feedback(db,cid,data['proposition_id'],actor,data['after_action'])
                else:return self.reply({'error':'unknown OODA action'},404)
                return self.reply({'event_id':result,'audit':check_audit(db,cid)})
            except (ValueError,KeyError,TypeError,sqlite3.Error,json.JSONDecodeError) as e:
                return self.reply({'error':str(e)},400)

    return ThreadingHTTPServer((bind,port),Handler)


if __name__=='__main__':
    p=argparse.ArgumentParser()
    p.add_argument('--db',default=str(DEFAULT_DB))
    p.add_argument('--base',default=str(DEFAULT_BASE))
    p.add_argument('--port',type=int,default=8922)
    p.add_argument('--token',default=None,help='Use an independent long random local secret')
    args=p.parse_args()
    token=args.token or secrets.token_urlsafe(32)
    srv=make_server(args.db,token,port=args.port,base=args.base)
    print('GMRI 4D Reorientation Viewer http://127.0.0.1:'+str(srv.server_address[1]),flush=True)
    print('Session token (never publish): '+token,flush=True)
    srv.serve_forever()
