"""Local read-only, agent-facing evidence retrieval over the GMRI graph.

Preserves the distinction between (a) original source, (b) explicitly assessed
reasoning edges, and (c) archival/lexical navigation. This module cannot perform
side effects, adjudicate personhood, or invent a warrant.
"""
from __future__ import annotations

import hashlib
import json
import sqlite3
from pathlib import Path
from typing import Any

from graph import evidence_trace, feedback_cycles, paths
from query_reasoning import fts

SCOPED_FAMILIES = ('github', 'library')


def readonly(path):
    p = Path(path).resolve()
    if not p.is_file():
        raise FileNotFoundError(str(p))
    c = sqlite3.connect(p.as_uri() + '?mode=ro', uri=True)
    c.row_factory = sqlite3.Row
    c.execute('PRAGMA query_only=ON')
    c.execute('PRAGMA busy_timeout=30000')
    return c


def json_safe(obj):
    return json.loads(json.dumps(obj, ensure_ascii=False))


class AssistantBridge:
    def __init__(self, reasoning_db: str | Path, archive_db: str | Path | None = None):
        self.reasoning_db = Path(reasoning_db).resolve()
        self.archive_db = Path(archive_db).resolve() if archive_db else None
        with readonly(self.reasoning_db) as c:
            required = {'proposition','source_document','reasoning_relation','proposition_fts'}
            found = {r[0] for r in c.execute('SELECT name FROM sqlite_master')}
            if not required.issubset(found):
                raise ValueError('not a GMRI source-backed reasoning database')
        if self.archive_db:
            with readonly(self.archive_db) as c:
                found = {r[0] for r in c.execute('SELECT name FROM sqlite_master')}
                if not {'nodes','edges','nodes_fts'}.issubset(found):
                    raise ValueError('not a GMRI historical evidence archive')

    def status(self) -> dict:
        with readonly(self.reasoning_db) as c:
            props = c.execute('SELECT count(*) FROM proposition').fetchone()[0]
            relationships = c.execute('SELECT count(*) FROM reasoning_relation').fetchone()[0]
            hypotheses = c.execute("SELECT count(*) FROM reasoning_relation WHERE status='hypothesis_not_evidence'").fetchone()[0]
            sources = c.execute('SELECT count(*) FROM source_document').fetchone()[0]
            try:
                metrics = dict(c.execute('SELECT metric,value FROM universe_metrics'))
            except sqlite3.OperationalError:
                metrics = {}
        result = {
            'role': 'model_retrieval_before_answer',
            'semantic_assessed_propositions': props,
            'typed_warranted_relationships': relationships,
            'hypothesis_relationships': hypotheses,
            'source_documents': sources,
            'archive_reference_metrics': metrics,
            'source_families': list(SCOPED_FAMILIES),
            'source_families_meaning': 'authorized scope, not claim of complete acquisition',
            'source_acquisition_complete': False,
            'reasoning_reconstruction_complete': False,
            'source_integrity_policy': 'sha256_of_full_source_and_exact_span',
        }
        if self.archive_db:
            with readonly(self.archive_db) as c:
                result['archive_nodes'] = c.execute('SELECT count(*) FROM nodes').fetchone()[0]
                result['archive_relationships'] = c.execute('SELECT count(*) FROM edges').fetchone()[0]
        return result

    def _reasoning_matches(self, question: str, limit: int) -> list[str]:
        query = fts(question)
        if not query:
            return []
        with readonly(self.reasoning_db) as c:
            try:
                ids = c.execute('''SELECT proposition_id FROM proposition_fts
                                    WHERE proposition_fts MATCH ?
                                    ORDER BY bm25(proposition_fts) LIMIT ?''', (query, limit)).fetchall()
            except sqlite3.OperationalError:
                return []
            return [r[0] for r in ids]

    def _archive_matches(self, question: str, limit: int) -> list[dict]:
        if not self.archive_db or not fts(question):
            return []
        with readonly(self.archive_db) as c:
            try:
                rows = c.execute('''SELECT n.id,n.kind,n.label,n.body,n.source_id,
                                   n.event_ts,n.recorded_ts,n.metadata_json
                                   FROM nodes_fts AS f JOIN nodes AS n ON n.id=f.node_id
                                   WHERE nodes_fts MATCH ?
                                   ORDER BY bm25(nodes_fts) LIMIT ?''',(fts(question),limit)).fetchall()
            except sqlite3.OperationalError:
                return []
        out=[]
        for r in rows:
            body=r['body'] or ''
            out.append({
                'id':r['id'],'kind':r['kind'],'label':r['label'],
                'source_id':r['source_id'],
                'body_excerpt':body[:1200],
                'body_length':len(body),
                'body_sha256':hashlib.sha256(body.encode('utf8')).hexdigest(),
                'event_ts':r['event_ts'],'recorded_ts':r['recorded_ts'],
                'status':'archived_text_not_semantic_verification',
                'retrieval_method':'lexical_locator_only',
            })
        return out

    def context(self, question: str, max_propositions: int = 8, max_archive: int = 8,
                max_cycles: int = 5) -> dict:
        if not isinstance(question,str) or not question.strip():
            raise ValueError('question must be nonempty')
        if not 1 <= max_propositions <= 30 or not 0 <= max_archive <= 40 or not 0 <= max_cycles <= 10:
            raise ValueError('retrieval bounds exceeded')
        seeds = self._reasoning_matches(question,max_propositions)
        propositions = []
        for id in seeds:
            t=evidence_trace(self.reasoning_db,id,depth=0)
            propositions.append({
                'id':id,'quote':t['verbatim'],'author':t['author'],
                'state':t['state'],'locator':t['locator'],
                'source_id':t['source_id'],'source_sha256':t['source_sha256'],
                'source_quote_verified':t['source_quote_verified'],
                'event_at':t['event_at'],'recorded_at':t['recorded_at'],
            })
        relation_rows=[]
        cycles=[]
        if seeds:
            unique_rel = {}
            with readonly(self.reasoning_db) as c:
                placeholders = ','.join('?' for _ in seeds)
                for r in c.execute(f'''SELECT src,dst,kind,warrant,method,status
                           FROM reasoning_relation WHERE src IN ({placeholders})
                           OR dst IN ({placeholders}) ORDER BY src,dst,kind''',seeds+seeds):
                    d=dict(r)
                    unique_rel[(d['src'],d['dst'],d['kind'])]=d
            # Only warranted, assessed edges. Do not invent implicit matches.
            relation_rows=list(unique_rel.values())[:120]
            if max_cycles:
                seen=set()
                for seed in seeds:
                    for loop in feedback_cycles(self.reasoning_db,seed,max_hops=8,max_cycles=max_cycles):
                        fingerprint=tuple((e['src'],e['dst'],e['kind']) for e in loop['edges'])
                        if fingerprint in seen: continue
                        seen.add(fingerprint)
                        cycles.append(loop)
                        if len(cycles)>=max_cycles:break
                    if len(cycles)>=max_cycles:break
        archive_records = self._archive_matches(question,max_archive) if max_archive else []
        answer_constraint = ('respond_only_from_cited_propositions_and_explicitly_marked_inferences'
                if propositions or archive_records else 'unknown_from_available_record')
        return {
            'mode':'for_assistant_before_answer',
            'question_verbatim':question,
            'propositions':propositions,
            'warranted_relations':relation_rows,
            'feedback_cycles':cycles,
            'archive_records':archive_records,
            'answer_constraint':answer_constraint,
            'evidence_contract':{
                'source_verbatim_preserved':True,
                'automatic_causation':False,
                'user_statements_are_not_assistant_paraphrases':True,
                'archive_links_are_not_reasoning_relations':True,
                'hypotheses_are_not_empirical_findings':True,
                'never_rewrite_user_intent':True,
            },
            'warning':'This is retrieval from available sources, not proof of complete original research coverage.',
        }

    def record(self, record_id: str, max_chars: int = 20000, offset: int = 0) -> dict:
        if not isinstance(record_id,str) or not record_id:
            raise ValueError('record ID required')
        if not 1 <= max_chars <= 100000 or not 0 <= offset <= 50000000:
            raise ValueError('record chunk bounds invalid')
        with readonly(self.reasoning_db) as c:
            exists=c.execute('SELECT 1 FROM proposition WHERE id=?',(record_id,)).fetchone()
        if exists:
            t = evidence_trace(self.reasoning_db,record_id,depth=0)
            body=t['source_body']
            return {
                'kind':'proposition','id':record_id,
                'quote':t['verbatim'],'quote_verified':t['source_quote_verified'],
                'source_text_full':body, 'source_sha256':t['source_sha256'],
                'source_locator':t['locator'],'state':t['state'],
                'source_author':t['author'],'source_span_offsets':t['offsets'],
                'chunk':body[offset:offset+max_chars],
                'next_offset':(offset+max_chars if offset+max_chars<len(body) else None),
            }
        if not self.archive_db:raise KeyError(record_id)
        with readonly(self.archive_db) as c:
            r=c.execute('SELECT * FROM nodes WHERE id=?',(record_id,)).fetchone()
        if not r:raise KeyError(record_id)
        body=r['body'] or ''
        body_sha=hashlib.sha256(body.encode('utf8')).hexdigest()
        with readonly(self.reasoning_db) as c:
            try:
                orig=c.execute('SELECT body_sha256 FROM universe_node WHERE node_id=?',(record_id,)).fetchone()
            except sqlite3.OperationalError:
                orig=None
        if orig and orig[0]!=body_sha:raise ValueError('archive source mutated after indexing')
        return {
            'kind':'archived_source_record', 'id':record_id,
            'source_id':r['source_id'],'source_sha256':body_sha,
            'body_length':len(body),'source_text_full':body if len(body)<=max_chars else None,
            'chunk':body[offset:offset+max_chars],
            'next_offset':(offset+max_chars if offset+max_chars<len(body) else None),
            'archive_registration_valid': bool(orig and orig[0]==body_sha),
            'claim_status':'not_semantically_assessed',
            'recorded_ts':r['recorded_ts'],'event_ts':r['event_ts'],
        }

    def trace(self, source_id: str, target_id: str | None = None,
              max_hops: int = 7, max_paths: int = 10) -> dict:
        if not 1<=max_hops<=12 or not 1<=max_paths<=30:
            raise ValueError('trace bounds invalid')
        if target_id:
            ps=paths(self.reasoning_db,source_id,target_id,max_hops=max_hops,max_paths=max_paths)
            return {'from':source_id,'to':target_id,'reasoning_paths':ps,
                    'evidence_rule':'every path edge requires independently assessed warrant',
                    'unknown_when_empty':not bool(ps)}
        cs=feedback_cycles(self.reasoning_db,source_id,max_hops=max_hops,max_cycles=max_paths)
        return {'anchor':source_id,'cycles':cs,'cycle_is_not_causal_proof':True}

    def ooda_targets(self, cycle_id: str, max_candidates: int=25) -> dict:
        from ooda_layers import orientation_targets
        return orientation_targets(self.reasoning_db,cycle_id,max_candidates=max_candidates)

    def tool_definitions(self) -> list[dict]:
        specs = [
            ('gmri_context','Retrieve preserved user/source propositions, warranted reasoning links, candidate feedback cycles, and archival source locators BEFORE answering.',
             {'question':{'type':'string'},'max_propositions':{'type':'integer','minimum':1,'maximum':30},'max_archive':{'type':'integer','minimum':0,'maximum':40},'max_cycles':{'type':'integer','minimum':0,'maximum':10}},['question']),
            ('gmri_get_record','Read exact cited proposition or historical record; return SHA-256 and bounded chunks.',
             {'record_id':{'type':'string'},'max_chars':{'type':'integer','minimum':1,'maximum':100000},'offset':{'type':'integer','minimum':0}},['record_id']),
            ('gmri_trace','Follow assessed reasoning paths between propositions or explicit feedback cycles, preserving edge warrants.',
             {'source_id':{'type':'string'},'target_id':{'type':'string'},'max_hops':{'type':'integer','minimum':1,'maximum':12},'max_paths':{'type':'integer','minimum':1,'maximum':30}},['source_id']),
            ('gmri_ooda_targets','Read the next evidence candidates from an existing OODA cycle without executing actions.',
             {'cycle_id':{'type':'string'},'max_candidates':{'type':'integer','minimum':1,'maximum':500}},['cycle_id']),
            ('gmri_scope_status','Report evidence coverage, source inventory and distinct semantic interpretation counts.',{},[]),
        ]
        return [
          {'name':name,'description':description,
           'inputSchema':{'type':'object','properties':props,'required':required,'additionalProperties':False}}
          for name,description,props,required in specs
        ]

    def call(self, name: str, args: dict | None = None) -> dict:
        if not isinstance(args,(dict,type(None))):raise ValueError('arguments must be object')
        args=args or {}
        if name=='gmri_context':return self.context(**args)
        if name=='gmri_get_record':return self.record(**args)
        if name=='gmri_trace':return self.trace(**args)
        if name=='gmri_ooda_targets':return self.ooda_targets(**args)
        if name=='gmri_scope_status':return self.status()
        raise KeyError('unauthorized tool: '+str(name))


if __name__=='__main__':
    import argparse
    p=argparse.ArgumentParser()
    p.add_argument('question',nargs='*')
    p.add_argument('--graph',required=True)
    p.add_argument('--archive')
    p.add_argument('--status',action='store_true')
