"""Local MCP stdio server for the GMRI reasoning evidence bridge.

Protocol: standard newline-delimited JSON-RPC 2.0 over stdin/stdout.
No network listener, credentials, mutation tools, or undeclared capabilities.
"""
from __future__ import annotations
import argparse
import json
import sys
from assistant_bridge import AssistantBridge


def encode_message(payload):
    return (json.dumps(payload,ensure_ascii=False,separators=(',',':'))+'\n').encode('utf8')


def decode_messages(data):
    # MCP stdio is newline-delimited JSON, not Content-Length HTTP framing.
    if isinstance(data,str):data=data.encode('utf8')
    for line in data.splitlines():
        if line.strip():yield json.loads(line.decode('utf8'))


def _response(rid,result=None,error=None):
    out={'jsonrpc':'2.0','id':rid}
    if error is None:out['result']=result
    else:out['error']=error
    return out


def dispatch(request,bridge):
    if not isinstance(request,dict) or request.get('jsonrpc')!='2.0':
        return _response(request.get('id') if isinstance(request,dict) else None,
                         error={'code':-32600,'message':'Invalid Request'})
    rid=request.get('id');method=request.get('method');params=request.get('params') or {}
    if rid is None:
        # notifications/initialized requires no response
        return None
    try:
        if method=='initialize':
            result={'protocolVersion':'2024-11-05',
                    'capabilities':{'tools':{'listChanged':False}},
                    'serverInfo':{'name':'gmri-reasoning-bridge','version':'0.1.0'}}
        elif method=='ping':result={}
        elif method=='tools/list':result={'tools':bridge.tool_definitions()}
        elif method=='tools/call':
            name=params.get('name')
            if name not in {x['name'] for x in bridge.tool_definitions()}:
                raise KeyError('tool not permitted: '+str(name))
            arguments=params.get('arguments') or {}
            allowed=next(x['inputSchema']['properties'] for x in bridge.tool_definitions() if x['name']==name)
            if set(arguments)-set(allowed):raise ValueError('unrecognized tool parameters')
            output=bridge.call(name,arguments)
            result={'content':[{'type':'text','text':json.dumps(output,ensure_ascii=False)}],
                    'isError':False}
        else:
            return _response(rid,error={'code':-32601,'message':'Method not found'})
        return _response(rid,result)
    except (TypeError,ValueError,KeyError,IndexError) as e:
        return _response(rid,error={'code':-32602,'message':str(e)})
    except Exception as e:
        # Do not silently treat a failed evidence query as an empty valid graph.
        return _response(rid,error={'code':-32603,'message':str(e)})


def serve(bridge):
    for line in sys.stdin.buffer:
        try:
            requests=list(decode_messages(line))
            for request in requests:
                reply=dispatch(request,bridge)
                if reply is not None:
                    sys.stdout.buffer.write(encode_message(reply))
                    sys.stdout.buffer.flush()
        except Exception as e:
            sys.stdout.buffer.write(encode_message(_response(None,error={'code':-32700,'message':'Parse error: '+str(e)})))
            sys.stdout.buffer.flush()


if __name__=='__main__':
