"""GMRI Shared Reasoning Studio: original evidence + auditable operator teaching.

Preserves original graph files read-only. User annotations are separate, append-only
teaching events and never become experimentally validated causal assertions.
"""
from __future__ import annotations

import hashlib
import json
import re
import sqlite3
import time
import uuid
from pathlib import Path
from typing import Any

SCHEMA = 'GMRI_TEACH_V1'
RELATIONS = ('FEEDS_BACK','CONSTRAINS','REQUIRES','REFINES','RECONTEXTUALIZES',
             'EXPLICIT_ANALOGY','SUPPORTS_CANDIDATE','EXPLICITLY_CONTRADICTS',
             'TEMPORAL_PRECEDENCE','DISTINGUISHES_FROM','NOT_A_RELATION','OTHER')
STEPS = ('Observe','Orient','Decide','Act','Feedback','Unassigned')

class TeachingError(ValueError):
    pass


def canonical(value):
    return json.dumps(value,sort_keys=True,ensure_ascii=False,separators=(',',':'))


def digest(value):
    return hashlib.sha256(value.encode('utf8')).hexdigest()


def packet_text(event):
    payload={k:event[k] for k in ('schema','id','session_id','from','to','relation','verbatim','orientation','created_at','source_snapshot') if k in event}
    payload['payload_sha256']=digest(canonical(payload))
    return SCHEMA+'\n'+json.dumps(payload,indent=2,ensure_ascii=False)


def parse_packet(text):
    if not text.startswith(SCHEMA+'\n'):
        raise TeachingError('teaching packet must begin with '+SCHEMA)
    try:
        x=json.loads(text.split('\n',1)[1]); h=x.pop('payload_sha256')
    except (ValueError,KeyError) as e:
        raise TeachingError('invalid teaching packet') from e
    if x.get('schema')!=SCHEMA or digest(canonical(x))!=h:
        raise TeachingError('teaching packet integrity check failed')
    return x


def _read(path):
    c=sqlite3.connect(Path(path).resolve().as_uri()+'?mode=ro',uri=True,timeout=30)
    c.row_factory=sqlite3.Row
    c.execute('PRAGMA query_only=ON')
    return c


def _tokens(query):
    toks=re.findall(r'[\w-]{2,60}',query,flags=re.UNICODE)
    return [t for t in toks if t.strip('-')][:12]


class StudioStore:
    def __init__(self,archive_path,reasoning_path,teaching_path):
        self.archive_path=Path(archive_path).resolve()
        self.reasoning_path=Path(reasoning_path).resolve()
        self.teaching_path=Path(teaching_path).resolve()
        for path in (self.archive_path,self.reasoning_path):
            if not path.is_file(): raise FileNotFoundError(str(path))
        self.teaching_path.parent.mkdir(parents=True,exist_ok=True)
        with self._teaching() as c:
            c.executescript('''
            CREATE TABLE IF NOT EXISTS events(
                id TEXT PRIMARY KEY,session_id TEXT NOT NULL,created_at TEXT NOT NULL,
                from_id TEXT NOT NULL,to_id TEXT,relation TEXT NOT NULL,
                verbatim TEXT NOT NULL,orientation TEXT NOT NULL,
                payload TEXT NOT NULL,source_sha256 TEXT NOT NULL,
                status TEXT NOT NULL DEFAULT 'awaiting_assistant');
            CREATE TABLE IF NOT EXISTS audit(
                serial INTEGER PRIMARY KEY AUTOINCREMENT, event_id TEXT NOT NULL,
                action TEXT NOT NULL,actor TEXT NOT NULL,payload TEXT NOT NULL,
                previous_sha256 TEXT NOT NULL,entry_sha256 TEXT NOT NULL);
            CREATE TABLE IF NOT EXISTS replies(
                id INTEGER PRIMARY KEY AUTOINCREMENT,event_id TEXT NOT NULL,
                actor TEXT NOT NULL,response TEXT NOT NULL,created_at TEXT NOT NULL);
            CREATE INDEX IF NOT EXISTS idx_events_session ON events(session_id);
            CREATE INDEX IF NOT EXISTS idx_audit_event ON audit(event_id);
            ''')

    def _teaching(self):
        c=sqlite3.connect(self.teaching_path,timeout=30)
        c.row_factory=sqlite3.Row
        c.execute('PRAGMA busy_timeout=30000')
        return c

    def status(self):
        with _read(self.archive_path) as a,_read(self.reasoning_path) as r,self._teaching() as t:
            return {'archive_nodes':a.execute('SELECT count(*) FROM nodes').fetchone()[0],
                    'archive_links':a.execute('SELECT count(*) FROM edges').fetchone()[0],
                    'assessed_propositions':r.execute('SELECT count(*) FROM proposition').fetchone()[0],
                    'assessed_links':r.execute('SELECT count(*) FROM reasoning_relation').fetchone()[0],
                    'teaching_events':t.execute('SELECT count(*) FROM events').fetchone()[0],
                    'reviewed_events':t.execute("SELECT count(*) FROM events WHERE status='accepted_by_operator'").fetchone()[0],
                    'source_scope':'locally accessible GitHub and Library archival materials; not a complete ingestion claim',
                    'session_mode':'annotations separated from original evidence'}

    def get_node(self,node_id):
        if not isinstance(node_id,str) or not node_id or len(node_id)>400:
            raise TeachingError('bad node identifier')
        with _read(self.reasoning_path) as c:
            row=c.execute('''SELECT p.id,p.quote,p.state,p.source_id,s.full_text,s.locator,
                        s.text_sha256,s.author,s.event_at,s.recorded_at FROM proposition p
                        JOIN source_document s ON p.source_id=s.id WHERE p.id=?''',(node_id,)).fetchone()
            if row:
                d=dict(row);text=d.pop('full_text');correct=digest(text)==d.pop('text_sha256')
                if not correct:raise TeachingError('original source hash mismatch')
                return {'id':d['id'],'classification':'assessed_proposition', 'kind':'proposition',
                        'label':d['quote'][:110], 'quote':d['quote'], 'source_id':d['source_id'],
                        'source_locator':d['locator'],'author':d['author'],'evidence_state':d['state'],
                        'event_ts':d['event_at'],'recorded_ts':d['recorded_at'],
                        'source_hash_verified':correct}
        with _read(self.archive_path) as c:
            row=c.execute('''SELECT id,kind,label,body,source_id,event_ts,recorded_ts,
                             metadata_json FROM nodes WHERE id=?''',(node_id,)).fetchone()
            if row:
                d=dict(row);body=d.pop('body') or ''
                d['classification']='archival_record_not_assessed_claim'
                d['quote']=body[:2200]
                d['body_length']=len(body)
                d['body_sha256']=digest(body)
                d['source_hash_verified']=False
                return d
        raise TeachingError('node not found in source databases: '+node_id)

    def search(self,query,limit=24):
        if not isinstance(query,str): raise TeachingError('query must be text')
        terms=_tokens(query)
        if not terms:return {'query':query,'results':[]}
        limit=max(1,min(int(limit),70)); q=' OR '.join('"'+x.replace('"','')+'"' for x in terms)
        ids=[]
        with _read(self.reasoning_path) as c:
            try:
                ids += [r[0] for r in c.execute('''SELECT p.id FROM proposition_fts f
                    JOIN proposition p ON p.id=f.proposition_id WHERE proposition_fts MATCH ?
                    LIMIT ?''',(q,limit)).fetchall()]
            except sqlite3.OperationalError:pass
        with _read(self.archive_path) as c:
            try:
                ids += [r[0] for r in c.execute('''SELECT n.id FROM nodes_fts f
                    JOIN nodes n ON n.id=f.node_id WHERE nodes_fts MATCH ? ORDER BY bm25(nodes_fts)
                    LIMIT ?''',(q,limit)).fetchall()]
            except sqlite3.OperationalError:pass
        found=[]
        for node_id in dict.fromkeys(ids):
            found.append(self.get_node(node_id))
            if len(found)>=limit:break
        return {'query':query,'results':found}

    def neighborhood(self,node_id,hops=1,limit=70):
        if not isinstance(hops,int) or hops<0 or hops>3:raise TeachingError('hops must be 0..3')
        limit=max(3,min(int(limit),120)); self.get_node(node_id)
        visited={node_id}; frontier=[node_id]; edge_by_id={}
        with _read(self.reasoning_path) as r,_read(self.archive_path) as a:
            for _ in range(hops):
                next_frontier=[]
                for current in frontier[:limit]:
                    rels=r.execute('''SELECT src,dst,kind,warrant,method,status FROM reasoning_relation
                                WHERE src=? OR dst=? LIMIT 120''',(current,current)).fetchall()
                    for e in rels:
                        d=dict(e);src,dst=d['src'],d['dst']
                        edge_id='reason:'+src+':'+dst+':'+d['kind'];edge_by_id[edge_id]={
                            'id':edge_id,'from':src,'to':dst,'type':d['kind'],'layer':'assessed',
                            'status':d['status'],'warrant':d['warrant'],'method':d['method']}
                        for v in (src,dst):
                            if v not in visited and len(visited)<limit:
                                visited.add(v);next_frontier.append(v)
                    arch=a.execute('''SELECT id,src,dst,relation,evidence_state,source_id FROM edges
                                  WHERE src=? OR dst=? LIMIT 120''',(current,current)).fetchall()
                    for e in arch:
                        d=dict(e);src,dst=d['src'],d['dst'];edge_id='archive:'+str(d['id'])
                        edge_by_id[edge_id]={'id':edge_id,'from':src,'to':dst,'type':d['relation'],
                           'layer':'archive','status':d['evidence_state'], 'source_id':d['source_id']}
                        for v in (src,dst):
                            if v not in visited and len(visited)<limit:
                                visited.add(v);next_frontier.append(v)
                frontier=next_frontier
                if not frontier:break
        valid_nodes={v:self.get_node(v) for v in visited}
        edges=[e for e in edge_by_id.values() if e['from'] in valid_nodes and e['to'] in valid_nodes]
        edges.sort(key=lambda x:(x['layer']!='assessed',x['type'],x['id']))
        return {'focus':node_id,'nodes':list(valid_nodes.values()),'edges':edges[:limit*4],
                'provenance':'assessed edges and archival edges retain distinct statuses'}

    def _audit(self,c,event_id,action,actor,record):
        prev=c.execute('SELECT entry_sha256 FROM audit ORDER BY serial DESC LIMIT 1').fetchone()
        prev=prev[0] if prev else 'GENESIS'
        payload=canonical(record)
        new_hash=digest(canonical({'event_id':event_id,'action':action,'actor':actor,'payload':payload,'previous_sha256':prev}))
        c.execute('''INSERT INTO audit(event_id,action,actor,payload,previous_sha256,entry_sha256)
                     VALUES(?,?,?,?,?,?)''',(event_id,action,actor,payload,prev,new_hash))

    def teach(self,data):
        if not isinstance(data,dict):raise TeachingError('teaching entry must be an object')
        frm=data.get('from');to=data.get('to') or None
        self.get_node(frm)
        if to:self.get_node(to)
        relation=data.get('relation','OTHER');step=data.get('orientation','Unassigned')
        if relation not in RELATIONS or step not in STEPS:raise TeachingError('invalid relation or OODA stage')
        verbatim=data.get('verbatim')
        if not isinstance(verbatim,str) or len(verbatim.strip())<4 or len(verbatim)>25000:
            raise TeachingError('operator explanation must be original text, 4..25000 chars')
        session_id=data.get('session_id') or 'studio-default'
        if not isinstance(session_id,str) or not 1<=len(session_id)<=150:
            raise TeachingError('bad session id')
        source_snapshot={'from':self.get_node(frm),'to':self.get_node(to) if to else None}
        event={'schema':SCHEMA,'id':'teach:'+str(uuid.uuid4()),'session_id':session_id,
               'created_at':time.strftime('%Y-%m-%dT%H:%M:%SZ',time.gmtime()),
               'from':frm,'to':to,'relation':relation,'verbatim':verbatim,
               'orientation':step,'source_snapshot':source_snapshot,
               'status':'awaiting_assistant','relation_status':'operator_proposal_not_empirical_proof'}
        with self._teaching() as c:
            c.execute('''INSERT INTO events(id,session_id,created_at,from_id,to_id,relation,
                         verbatim,orientation,payload,source_sha256,status)
                         VALUES(?,?,?,?,?,?,?,?,?,?,?)''',(
                event['id'],session_id,event['created_at'],frm,to,relation,verbatim,step,
                canonical(event),digest(verbatim),'awaiting_assistant'))
            self._audit(c,event['id'],'operator_teach','operator',event)
        return event

    def get_event(self,event_id):
        with self._teaching() as c:
            row=c.execute('SELECT payload,status FROM events WHERE id=?',(event_id,)).fetchone()
            if not row:raise TeachingError('teaching event not found')
            payload=json.loads(row['payload']);payload['status']=row['status']
            payload['replies']=[dict(x) for x in c.execute('SELECT actor,response,created_at FROM replies WHERE event_id=? ORDER BY id',(event_id,))]
            return payload

    def inbox(self,since=None,limit=100,session_id=None):
        limit=max(1,min(int(limit),250))
        with self._teaching() as c:
            sql='SELECT id,payload,status FROM events WHERE 1=1';params=[]
            if session_id:sql+=' AND session_id=?';params.append(session_id)
            if since:sql+=' AND rowid>?';params.append(int(since))
            sql+=' ORDER BY rowid DESC LIMIT ?';params.append(limit)
            rows=c.execute(sql,params).fetchall()
            events=[]
            for row in rows:
                e=json.loads(row['payload']);e['status']=row['status'];events.append(e)
            return {'events':events,'audit':self.verify_audit()}

    def assistant_reply(self,event_id,text):
        if not isinstance(text,str) or not 1<=len(text)<=25000:
            raise TeachingError('assistant response required')
        with self._teaching() as c:
            if not c.execute('SELECT 1 FROM events WHERE id=?',(event_id,)).fetchone():
                raise TeachingError('unknown teaching event')
            now=time.strftime('%Y-%m-%dT%H:%M:%SZ',time.gmtime())
            c.execute('INSERT INTO replies(event_id,actor,response,created_at) VALUES(?,?,?,?)',
                     (event_id,'assistant',text,now))
            c.execute("UPDATE events SET status='assistant_replied' WHERE id=? AND status='awaiting_assistant'",(event_id,))
            self._audit(c,event_id,'assistant_response','assistant',{'text':text,'at':now})
        return self.get_event(event_id)

    def review(self,event_id,verdict,actor='operator'):
        if actor!='operator':raise TeachingError('only the operator may approve or reject interpretations')
        if verdict not in {'accepted','rejected','needs_correction'}:
            raise TeachingError('invalid review')
        with self._teaching() as c:
            if not c.execute('SELECT 1 FROM events WHERE id=?',(event_id,)).fetchone():
                raise TeachingError('unknown teaching event')
            status={'accepted':'accepted_by_operator','rejected':'rejected_by_operator','needs_correction':'needs_correction'}[verdict]
            c.execute('UPDATE events SET status=? WHERE id=?',(status,event_id))
            self._audit(c,event_id,'operator_review','operator',{'verdict':verdict,'status':status})
        return self.get_event(event_id)

    def verify_audit(self):
        with self._teaching() as c:
            rows=c.execute('SELECT * FROM audit ORDER BY serial').fetchall()
        prev='GENESIS'
