            if e['previous_sha256']!=prev or e['entry_sha256']!=want:
                return {'valid':False,'offending_serial':e['serial']}
            prev=e['entry_sha256']
        return {'valid':True,'entries':len(rows),'last_sha256':prev}

    def export_session(self,session_id):
        e=self.inbox(limit=250,session_id=session_id)
        return {'schema':'GMRI_STUDIO_SESSION_V1','session_id':session_id,
                'events':e['events'],'audit_valid':e['audit']['valid'],
                'source_notice':'Original archive and assessed reasoning are unchanged. Teaching is a distinct reviewable ledger.'}
