"""Authenticated local shared teaching surface. No cloud upload or default LAN exposure."""
from __future__ import annotations
import json
import os
import secrets
from pathlib import Path
from fastapi import Depends, FastAPI, HTTPException, Request
from fastapi.responses import FileResponse, JSONResponse
from pydantic import BaseModel
from studio_core import StudioStore, TeachingError, packet_text

class TeachRequest(BaseModel):
    session_id:str='studio-default'
    from_:str|None=None
    to:str|None=None
    relation:str='OTHER'
    verbatim:str
    orientation:str='Unassigned'

class ResponseRequest(BaseModel):
    text:str

class ReviewRequest(BaseModel):
    verdict:str


def create_app(store:StudioStore,token:str,static_dir:Path|None=None):
    if not token or len(token)<8:raise ValueError('access key must have at least 8 characters')
    app=FastAPI(title='GMRI Shared Reasoning Studio',docs_url=None,redoc_url=None,openapi_url=None)
    static_dir=Path(static_dir) if static_dir else None

    @app.middleware('http')
    async def headers(request:Request,call_next):
        response=await call_next(request)
        response.headers['Cache-Control']='no-store'
        response.headers['X-Content-Type-Options']='nosniff'
        response.headers['Referrer-Policy']='no-referrer'
        response.headers['X-Frame-Options']='DENY'
        return response

    def auth(request:Request):
        key=request.headers.get('X-GMRI-Session','')
        if not secrets.compare_digest(key,token):raise HTTPException(status_code=401,detail='private key required')

    @app.exception_handler(TeachingError)
    async def teaching_error(request:Request,exc:TeachingError):
        return JSONResponse(status_code=400,content={'error':str(exc)})

    @app.get('/')
    def index():
        if not static_dir:return {'service':'GMRI Studio','usage':'/api/status with X-GMRI-Session'}
        return FileResponse(static_dir/'index.html',media_type='text/html')

    @app.get('/app.js')
    def js():
        if not static_dir:raise HTTPException(404)
        return FileResponse(static_dir/'app.js',media_type='text/javascript')

    @app.get('/app.css')
    def css():
        if not static_dir:raise HTTPException(404)
        return FileResponse(static_dir/'app.css',media_type='text/css')

    @app.get('/api/status',dependencies=[Depends(auth)])
    def status():return store.status()

    @app.get('/api/search',dependencies=[Depends(auth)])
    def search(q:str='',limit:int=24):return store.search(q,limit)

    @app.get('/api/node',dependencies=[Depends(auth)])
    def node(id:str):return store.get_node(id)

    @app.get('/api/neighborhood',dependencies=[Depends(auth)])
    def neighborhood(id:str,hops:int=1,limit:int=70):return store.neighborhood(id,hops,limit)

    @app.get('/api/inbox',dependencies=[Depends(auth)])
    def inbox(session_id:str|None=None,limit:int=100):return store.inbox(limit=limit,session_id=session_id)

    @app.post('/api/teach',dependencies=[Depends(auth)])
    async def teach(request:Request):
        data=await request.json()
        return store.teach(data)

    @app.post('/api/assistant/reply/{event_id}',dependencies=[Depends(auth)])
    async def reply(event_id:str,request:Request):
        data=await request.json();return store.assistant_reply(event_id,data.get('text'))

    @app.post('/api/operator/review/{event_id}',dependencies=[Depends(auth)])
    async def review(event_id:str,request:Request):
        data=await request.json();return store.review(event_id,data.get('verdict'),actor='operator')

    @app.get('/api/packet/{event_id}',dependencies=[Depends(auth)])
    def packet(event_id:str):return {'text':packet_text(store.get_event(event_id))}

    @app.get('/api/export',dependencies=[Depends(auth)])
    def export(session_id:str='studio-default'):return store.export_session(session_id)

    @app.get('/api/verify',dependencies=[Depends(auth)])
    def verify():return store.verify_audit()
    return app


def run():
    import argparse
