"""Standard local MCP stdio tool service for the same GMRI graph and teaching ledger.

Run by an authorized local assistant. No network listener. Operator alone may
approve/reject. All original evidence databases are opened read-only.
"""
import argparse
import json
import sys
from pathlib import Path
from studio_core import StudioStore

ROOT=Path(__file__).resolve().parent
DATA=ROOT/'DATA'

TOOLS={
 'gmri_studio_focus':('Read which original source IDs the operator has selected in a lesson.',{'session_id':('string','Session identifier','studio-default')}),
 'gmri_studio_inbox':('Read original operator teaching statements, exact IDs, statuses, and source snapshots.',{'session_id':('string','Session identifier','studio-default')}),
 'gmri_studio_event':('Read one teaching event and assistant replies.',{'event_id':('string','Exact teaching event ID',None)}),
 'gmri_studio_search':('Search assessed and archival graph nodes; do not treat lexical matches as causal proofs.',{'query':('string','Original search terms',None)}),
 'gmri_studio_node':('Read one original node, its identifier and evidence classification.',{'node_id':('string','Exact graph node ID',None)}),
 'gmri_studio_neighbors':('Follow actual archival and separately assessed graph relationships.',{'node_id':('string','Exact graph node ID',None),'hops':('integer','Hops, 0 through 3',1)}),
 'gmri_studio_text':('Read a bounded slice of original source text; report whether source hash was verified.',{'node_id':('string','Exact graph node ID',None),'offset':('integer','Character offset',0),'limit':('integer','Character limit, maximum 5000',3000)}),
 'gmri_studio_reply':('Record assistant interpretation in the teaching ledger; only the operator can accept it.',{'event_id':('string','Exact teaching event ID',None),'text':('string','Assistant reply, distinct from original operator words',None)}),
 'gmri_studio_verify':('Verify the append-only teaching audit chain.',{}),
 'gmri_studio_status':('Read original archival and assessed graph scope without treating counts as semantic coverage.',{}),
}

def definitions():
    out=[]
    for name,(description,spec) in TOOLS.items():
        props={k:{'type':typ,'description':desc} for k,(typ,desc,default) in spec.items()}
        required=[k for k,(_,_,default) in spec.items() if default is None]
        out.append({'name':name,'description':description,
                    'inputSchema':{'type':'object','properties':props,'required':required,'additionalProperties':False}})
    return out

def _call(name,args,store):
    if name=='gmri_studio_focus':return store.get_focus(args.get('session_id','studio-default'))
    if name=='gmri_studio_inbox':return store.inbox(session_id=args.get('session_id','studio-default'))
    if name=='gmri_studio_event':return store.get_event(args['event_id'])
    if name=='gmri_studio_search':return store.search(args['query'])
    if name=='gmri_studio_node':return store.get_node(args['node_id'])
    if name=='gmri_studio_neighbors':return store.neighborhood(args['node_id'],hops=args.get('hops',1))
    if name=='gmri_studio_text':return store.text_slice(args['node_id'],offset=args.get('offset',0),limit=args.get('limit',3000))
    if name=='gmri_studio_reply':return store.assistant_reply(args['event_id'],args['text'])
    if name=='gmri_studio_verify':return store.verify_audit()
    if name=='gmri_studio_status':return store.status()
    raise ValueError('unknown studio tool')

def dispatch(request,store):
    rid=request.get('id') if isinstance(request,dict) else None
    def reply(data=None,err=None):
        z={'jsonrpc':'2.0','id':rid}
        if err:z['error']={'code':-32602,'message':str(err)}
        else:z['result']=data
        return z
    if not isinstance(request,dict) or request.get('jsonrpc')!='2.0':return reply(err='Invalid Request')
    if rid is None:return None
    method=request.get('method')
    if method=='initialize':return reply({'protocolVersion':'2024-11-05',
         'serverInfo':{'name':'gmri-shared-studio','version':'1.0.0'},'capabilities':{'tools':{'listChanged':False}}})
    if method=='ping':return reply({})
    if method=='tools/list':return reply({'tools':definitions()})
    if method!='tools/call':return reply(err='Method not found')
    params=request.get('params') or {};name=params.get('name');args=params.get('arguments') or {}
    if name not in TOOLS:return reply(err='Tool not available')
    if not isinstance(args,dict):return reply(err='Arguments must be an object')
    spec=TOOLS[name][1]
    if set(args)-set(spec):return reply(err='Unrecognized tool parameters')
    if any(key not in args for key,(_,_,default) in spec.items() if default is None):return reply(err='Required parameters missing')
    try:
        result=_call(name,args,store)
        return reply({'content':[{'type':'text','text':json.dumps(result,ensure_ascii=False)}], 'isError':False})
    except Exception as exc:
        return reply(err=str(exc))

def serve(store):
    for line in sys.stdin.buffer:
        if not line.strip():continue
        try:
            request=json.loads(line)
            result=dispatch(request,store)
            if result is not None:
                sys.stdout.write(json.dumps(result,ensure_ascii=False)+'\n');sys.stdout.flush()
        except Exception as exc:
            sys.stdout.write(json.dumps({'jsonrpc':'2.0','id':None,'error':{'code':-32700,'message':str(exc)}})+'\n')
            sys.stdout.flush()

if __name__=='__main__':
    p=argparse.ArgumentParser();p.add_argument('--archive',default=str(DATA/'archive.sqlite'))
    p.add_argument('--reasoning',default=str(DATA/'reasoning.sqlite'))
    p.add_argument('--teaching',default=str(DATA/'teaching.sqlite'))
    a=p.parse_args()
    serve(StudioStore(a.archive,a.reasoning,a.teaching))
